insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('forgiveness-ledger', 'Forgiveness Ledger', 'worksheet'::resource_kind, 'Separates what a client is ready to let go of from what still needs time, one grievance at a time.', 'Give the client language for partial forgiveness instead of an all-or-nothing verdict.', array['Adults']::text[], '20 minutes', 'Have the client list a grievance, what happened, and what forgiving it would and would not mean, since it does not mean approval or renewed contact. Some entries will sort into ready, others into not yet, and both are fine outcomes. Revisit the ledger every few weeks rather than pushing for resolution in one sitting.', '[{"id": "f0", "type": "textarea", "label": "A grievance I am carrying"}, {"id": "f1", "type": "textarea", "label": "What happened, in a sentence or two"}, {"id": "f2", "type": "textarea", "label": "What forgiving this would NOT mean for me"}, {"id": "f3", "type": "textarea", "label": "Where this sits right now: ready, partway, or not yet"}, {"id": "f4", "type": "textarea", "label": "What is holding it back, if not ready"}, {"id": "f5", "type": "textarea", "label": "What I would need to move it forward"}]'::jsonb, array['forgiveness', 'self-monitoring', 'values']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('life-transition-compass', 'Life Transition Compass', 'worksheet'::resource_kind, 'Maps what is ending, what is uncertain, and what is possible during a major life change.', 'Give the client a structure for a transition that otherwise feels shapeless.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to name the transition, a move, a job change, an ending relationship, retirement, and sort it into what is ending, what is currently uncertain, and what new possibility might open. Most transitions carry real loss alongside real opportunity, and naming both keeps the client from having to pick one feeling. Revisit the compass as the uncertain column resolves.', '[{"id": "f0", "type": "textarea", "label": "The transition I am in"}, {"id": "f1", "type": "textarea", "label": "What is ending"}, {"id": "f2", "type": "textarea", "label": "What is still uncertain"}, {"id": "f3", "type": "textarea", "label": "What might become possible"}, {"id": "f4", "type": "textarea", "label": "What I am grieving about this change"}, {"id": "f5", "type": "textarea", "label": "One small step that fits where I am now"}]'::jsonb, array['transitions', 'values', 'life review']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('overcommitment-pattern-map', 'Overcommitment Pattern Map', 'worksheet'::resource_kind, 'Traces the pattern behind a client''s yeses to find where overcommitment keeps starting.', 'Help the client spot the moment they say yes before they have decided to.', array['Adults']::text[], '20 minutes', 'Walk through three recent times the client agreed to something they later regretted, noting who asked, what they felt in the moment, and what they said instead of pausing. A pattern usually shows up fast: a person, a feeling, or a phrase that predicts the yes. Use the map to rehearse a delay line for next time rather than an outright no.', '[{"id": "f0", "type": "textarea", "label": "A recent time I said yes and regretted it"}, {"id": "f1", "type": "textarea", "label": "Who asked, and how"}, {"id": "f2", "type": "textarea", "label": "What I felt right before I answered"}, {"id": "f3", "type": "textarea", "label": "What I said instead of pausing"}, {"id": "f4", "type": "textarea", "label": "The pattern I notice across these examples"}, {"id": "f5", "type": "textarea", "label": "A delay line I could use next time"}]'::jsonb, array['boundaries', 'self-monitoring', 'assertiveness']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('weekend-reset-planner', 'Weekend Reset Planner', 'worksheet'::resource_kind, 'Plans a weekend around what actually restores a client instead of what fills the time.', 'Turn a client''s weekend from another to-do list into deliberate recovery.', array['Adults']::text[], '15 minutes', 'Have the client separate weekend hours into obligations that cannot move and open hours that can, then choose two or three restorative activities for the open hours before the week''s chores creep in. Ask what usually eats the open hours by default, since naming the default is often more useful than the plan itself. Review Monday morning what actually happened against the plan.', '[{"id": "f0", "type": "textarea", "label": "Obligations that cannot move this weekend"}, {"id": "f1", "type": "textarea", "label": "Open hours I actually have"}, {"id": "f2", "type": "textarea", "label": "What usually eats those hours by default"}, {"id": "f3", "type": "textarea", "label": "Two or three restorative things I want in there"}, {"id": "f4", "type": "textarea", "label": "What I will protect no matter what"}, {"id": "f5", "type": "textarea", "label": "How Monday morning actually felt"}]'::jsonb, array['burnout', 'routines', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('motivation-dip-troubleshooter', 'Motivation Dip Troubleshooter', 'worksheet'::resource_kind, 'Sorts a motivation slump into fatigue, unclear goals, or a mismatch with the client''s values.', 'Help the client sort out what kind of motivation dip this is instead of just pushing through it.', array['Adults', 'Teens']::text[], '15 minutes', 'Motivation dips have different causes and different fixes, so before troubleshooting, ask whether this looks more like fatigue, a goal that has gone fuzzy, or a task that stopped connecting to anything the client cares about. Each answer points to a different next step: rest, clarifying the goal, or reconnecting to a value. Avoid the client''s instinct to treat every dip as a discipline problem.', '[{"id": "f0", "type": "textarea", "label": "The task or goal I have lost steam on"}, {"id": "f1", "type": "textarea", "label": "How my energy has been lately"}, {"id": "f2", "type": "textarea", "label": "How clear the goal still feels"}, {"id": "f3", "type": "textarea", "label": "What this task connects to that I actually care about"}, {"id": "f4", "type": "textarea", "label": "Which of the three, rest, clarity, or values, fits best right now"}, {"id": "f5", "type": "textarea", "label": "One step that matches that answer"}]'::jsonb, array['motivation', 'values', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('mental-filter-spotlight', 'Mental Filter Spotlight', 'cbt'::resource_kind, 'Has the client find the one negative detail their mind kept while the rest of the day disappeared.', 'Show the client how a mental filter edits out everything that does not fit the low mood.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to describe a day, then ask what stuck with them by evening. Usually one flawed moment survives the edit while several fine or good ones do not, and naming that gap in front of the client is often the useful part. Practice rebuilding the fuller day from memory, moment by moment, to weaken the filter''s grip.', '[{"id": "f0", "type": "textarea", "label": "A day I want to look at"}, {"id": "f1", "type": "textarea", "label": "What stuck with me by evening"}, {"id": "f2", "type": "textarea", "label": "Other things that actually happened that day"}, {"id": "f3", "type": "textarea", "label": "Why I think the mind kept the one detail"}, {"id": "f4", "type": "textarea", "label": "What the fuller picture of the day looks like"}, {"id": "f5", "type": "textarea", "label": "A phrase to catch the filter next time"}]'::jsonb, array['thinking traps', 'core CBT', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('should-statements-rewrite', 'Should Statements Rewrite', 'cbt'::resource_kind, 'Rewrites a client''s should and must statements into flexible preferences they can actually live with.', 'Loosen the grip of a rigid rule before it turns into guilt or resentment.', array['Adults', 'Teens']::text[], '15 minutes', 'Collect a handful of the client''s should and must statements, then rewrite each one as a preference: what they would like, and why the original rule sets an unreachable standard. Notice which shoulds are aimed at the client and which are aimed at other people, since both tend to cause trouble. Keep the rewritten versions somewhere the client can find them when the old rule resurfaces.', '[{"id": "f0", "type": "textarea", "label": "A should or must statement I catch myself using"}, {"id": "f1", "type": "textarea", "label": "Who it is aimed at, me or someone else"}, {"id": "f2", "type": "textarea", "label": "What happens when I hold myself or others to it"}, {"id": "f3", "type": "textarea", "label": "The preference underneath the rule"}, {"id": "f4", "type": "textarea", "label": "A rewritten, more flexible version"}, {"id": "f5", "type": "textarea", "label": "Where I will keep this rewrite handy"}]'::jsonb, array['thinking traps', 'core beliefs', 'core CBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('mind-reading-check', 'Mind Reading Check', 'cbt'::resource_kind, 'Tests a client''s guess about what someone else is thinking against what they can actually know.', 'Slow down a confident guess about another person''s thoughts before it drives a decision.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client write down what they believe someone else is thinking about them, then separate that from any evidence they actually have, such as a comment or an expression. Most mind-reading guesses turn out to rest on very little. Ask what a more curious question to that person might sound like, and whether asking it is realistic here.', '[{"id": "f0", "type": "textarea", "label": "What I believe this person is thinking about me"}, {"id": "f1", "type": "textarea", "label": "The actual evidence I have for that"}, {"id": "f2", "type": "textarea", "label": "What else could explain their behavior"}, {"id": "f3", "type": "textarea", "label": "How confident I am in my guess, 0 to 100"}, {"id": "f4", "type": "textarea", "label": "A question I could ask instead of guessing"}, {"id": "f5", "type": "textarea", "label": "Whether asking it feels realistic here"}]'::jsonb, array['thinking traps', 'core CBT', 'assumptions']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('evidence-for-and-against-card', 'Evidence For and Against Card', 'cbt'::resource_kind, 'A quick two-column card for weighing the evidence on both sides of a stuck thought.', 'Give the client a faster tool than a full thought record for a thought that will not settle.', array['Adults', 'Teens']::text[], '10 minutes', 'This is the pocket version of a thought record for a client who will not sit down and do the full six columns: name the thought, list what supports it, list what does not, then write a fairer statement that accounts for both columns. Keep the card somewhere accessible so it gets used in the moment rather than saved for session. A few uses usually loosen the thought''s grip.', '[{"id": "f0", "type": "textarea", "label": "The thought I keep returning to"}, {"id": "f1", "type": "textarea", "label": "Evidence that supports it"}, {"id": "f2", "type": "textarea", "label": "Evidence that does not support it"}, {"id": "f3", "type": "textarea", "label": "A fairer statement that fits both columns"}, {"id": "f4", "type": "textarea", "label": "How believable the fairer statement feels, 0 to 100"}]'::jsonb, array['thinking traps', 'core CBT', 'evidence']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('thought-record-shortcut-card', 'Thought Record Shortcut Card', 'cbt'::resource_kind, 'A three-line version of a thought record built for use between sessions, not instead of one.', 'Keep the thought-record habit alive on a week the client will not do the full worksheet.', array['Adults', 'Teens']::text[], '10 minutes', 'Some weeks the full thought record is too much, so this asks for only three things: the situation, the automatic thought, and one alternative thought that also fits the facts. It is meant to keep the skill warm, not replace the longer version entirely. Bring the shortcut cards into session and expand the interesting ones together.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The automatic thought"}, {"id": "f2", "type": "textarea", "label": "An alternative thought that also fits the facts"}, {"id": "f3", "type": "textarea", "label": "Which one feels more true right now"}]'::jsonb, array['core CBT', 'thought record', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('unwanted-guest-metaphor', 'Unwanted Guest Metaphor', 'act'::resource_kind, 'Uses the image of an unwanted houseguest to explore making room for a difficult feeling.', 'Practice hosting a difficult feeling without giving it control of the house.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to imagine the feeling as a guest who showed up uninvited and refuses to leave; fighting the guest at the door takes all day, while going about the house anyway, guest included, leaves room for a life. Notice what the client''s usual strategy with the guest looks like: arguing, hiding, or appeasing. Practice imagining a day where the guest is present but not in charge.', '[{"id": "f0", "type": "textarea", "label": "The feeling this guest represents"}, {"id": "f1", "type": "textarea", "label": "What I usually do when this guest shows up"}, {"id": "f2", "type": "textarea", "label": "What arguing with the guest has cost me"}, {"id": "f3", "type": "textarea", "label": "What going about the house anyway would look like today"}, {"id": "f4", "type": "textarea", "label": "One thing I would do even with the guest present"}]'::jsonb, array['metaphor', 'acceptance', 'willingness']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('values-vs-goals-sort', 'Values vs Goals Sort', 'act'::resource_kind, 'Sorts a client''s list of goals into the underlying values that give each one its pull.', 'Show the client the difference between a goal they can finish and a value they keep living by.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client list several goals, then ask what each one is in service of; a goal is a checkbox, a value is a direction that stays useful even after the box is checked. Some goals will turn out to serve no clear value, which is worth noticing too. Use the sorted list to choose which goal to prioritize based on the value behind it, not just urgency.', '[{"id": "f0", "type": "textarea", "label": "A goal on my list"}, {"id": "f1", "type": "textarea", "label": "The value it is in service of"}, {"id": "f2", "type": "textarea", "label": "What still matters here even if the goal never finishes"}, {"id": "f3", "type": "textarea", "label": "A goal that, on reflection, does not connect to a value I hold"}, {"id": "f4", "type": "textarea", "label": "Which goal I want to prioritize, and why"}]'::jsonb, array['values', 'core ACT', 'goal setting']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('willingness-thermometer', 'Willingness Thermometer', 'act'::resource_kind, 'Rates a client''s willingness to feel a specific emotion, situation by situation, across a week.', 'Track willingness as its own skill instead of waiting for a feeling to become comfortable.', array['Adults', 'Teens']::text[], '10 minutes', 'Before a situation that usually triggers avoidance, have the client rate their willingness to feel whatever shows up, from fighting it off to making full room for it. Willingness is not the same as wanting the feeling or feeling calm about it, and the rating can move independently of both. Compare ratings across the week to see whether willingness is growing with practice.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The feeling I expect to show up"}, {"id": "f2", "type": "textarea", "label": "My willingness rating before, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What I actually did"}, {"id": "f4", "type": "textarea", "label": "My willingness rating after"}, {"id": "f5", "type": "textarea", "label": "What I notice across this week''s ratings"}]'::jsonb, array['willingness', 'acceptance', 'core ACT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('two-mountains-metaphor', 'Two Mountains Metaphor', 'act'::resource_kind, 'Compares the mountain a client is climbing to reach comfort against the one worth climbing for its own view.', 'Redirect effort from chasing comfort toward a climb the client actually values.', array['Adults', 'Teens']::text[], '15 minutes', 'Describe two mountains: one climbed only to feel better, which never quite has a summit, and one climbed because the view itself matters, discomfort included. Ask which mountain the client has been climbing lately and what it would mean to choose the other one on purpose. This is not about ignoring pain, only about choosing what the effort is for.', '[{"id": "f0", "type": "textarea", "label": "The mountain I have mostly been climbing"}, {"id": "f1", "type": "textarea", "label": "What I was hoping the summit would give me"}, {"id": "f2", "type": "textarea", "label": "A mountain worth climbing for its own view"}, {"id": "f3", "type": "textarea", "label": "What discomfort I would accept to climb that one"}, {"id": "f4", "type": "textarea", "label": "One step up that mountain I could take this week"}]'::jsonb, array['metaphor', 'values', 'core ACT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('mind-as-radio-station-practice', 'Mind as Radio Station Practice', 'act'::resource_kind, 'Practices noticing the mind''s running commentary the way a person notices background radio.', 'Build distance from automatic self-talk without arguing with it.', array['Adults', 'Teens']::text[], '10 minutes', 'Ask the client to imagine their thoughts as a radio station playing in the background, always broadcasting something, whether or not anyone is tuned in. The goal is not to turn the station off but to notice when it has taken over the foreground and gently turn the volume back down. Practice narrating a stretch of the day as the station is now saying, to build the habit of noticing.', '[{"id": "f0", "type": "textarea", "label": "A thought the station has been playing on repeat"}, {"id": "f1", "type": "textarea", "label": "What happens when I mistake the broadcast for the news"}, {"id": "f2", "type": "textarea", "label": "What I notice when I say, the station is now saying"}, {"id": "f3", "type": "textarea", "label": "What I would rather have in the foreground"}, {"id": "f4", "type": "textarea", "label": "A moment today I could try this"}]'::jsonb, array['defusion', 'core ACT', 'mindfulness']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('emotion-regulation-skills-menu', 'Emotion Regulation Skills Menu', 'dbt'::resource_kind, 'A personalized menu of emotion regulation skills sorted by which emotion each one targets.', 'Give the client a ready reference instead of trying to recall a skill mid-emotion.', array['Adults', 'Teens']::text[], '15 minutes to build, then ongoing', 'Work through the client''s usual difficult emotions one at a time and list which skill actually helps with each: opposite action for one, a self-soothe option for another, a cognitive skill for a third. A skill that works for anger will not always work for sadness, and building the menu in advance saves the client from improvising while already dysregulated. Keep the finished menu somewhere quick to reach.', '[{"id": "f0", "type": "textarea", "label": "An emotion I regularly struggle to manage"}, {"id": "f1", "type": "textarea", "label": "A skill that has actually helped with this one before"}, {"id": "f2", "type": "textarea", "label": "Another emotion that needs a different skill"}, {"id": "f3", "type": "textarea", "label": "What helps with that one"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this menu so I can find it fast"}]'::jsonb, array['emotion regulation', 'skills', 'core DBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('between-sessions-skills-diary', 'Between Sessions Skills Diary', 'dbt'::resource_kind, 'A brief daily log of which DBT skill the client reached for and whether it helped.', 'Track skills use across the week instead of relying on memory in session.', array['Adults', 'Teens']::text[], 'Ongoing, a few minutes daily', 'Each day, have the client note one moment a skill was needed, which one they used, and how it went, even a partial or failed attempt. The point is not a perfect record but a running sense of which skills are actually getting used and which stay theoretical. Bring the diary into session to decide what to practice next.', '[{"id": "f0", "type": "textarea", "label": "The moment a skill was needed"}, {"id": "f1", "type": "textarea", "label": "The skill I reached for"}, {"id": "f2", "type": "textarea", "label": "How it went"}, {"id": "f3", "type": "textarea", "label": "A skill I meant to use but did not"}]'::jsonb, array['skills', 'core DBT', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('personal-crisis-survival-kit-card', 'Personal Crisis Survival Kit Card', 'dbt'::resource_kind, 'A single card listing the client''s own fastest distress tolerance skills, chosen in advance.', 'Cut the decision time between crisis and skill down to almost nothing.', array['Adults', 'Teens']::text[], '20 minutes to build, then in the moment', 'Rather than teach one crisis skill, build a short, personal list of the two or three that have actually worked for this client before, in the order they are willing to try them. Test the card at a lower distress level first so using it under real pressure is a rehearsal, not a first attempt. Include 988, call or text, as the last line on the card.', '[{"id": "f0", "type": "textarea", "label": "My first skill to try"}, {"id": "f1", "type": "textarea", "label": "My second skill, if the first is not enough"}, {"id": "f2", "type": "textarea", "label": "My third, if I am still struggling"}, {"id": "f3", "type": "textarea", "label": "Who I can call or text"}, {"id": "f4", "type": "textarea", "label": "988, call or text, if it gets worse than this"}, {"id": "f5", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['distress tolerance', 'crisis', 'core DBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('effectiveness-over-being-right-practice', 'Effectiveness Over Being Right Practice', 'dbt'::resource_kind, 'Practices choosing the response that works over the response that proves a point.', 'Shift the client''s goal in a hard moment from winning to getting what actually matters.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk through a recent conflict and ask two separate questions: what would have proven the client right, and what would have actually gotten them what they wanted. The two answers are often different, and dialectical thinking means the client can be right and still choose effectiveness. Practice picking the effective option even when the urge to be right is strong.', '[{"id": "f0", "type": "textarea", "label": "A recent moment I wanted to be right"}, {"id": "f1", "type": "textarea", "label": "What being right would have proven"}, {"id": "f2", "type": "textarea", "label": "What I actually wanted out of the situation"}, {"id": "f3", "type": "textarea", "label": "What the effective response would have looked like"}, {"id": "f4", "type": "textarea", "label": "What made choosing effectiveness hard"}, {"id": "f5", "type": "textarea", "label": "A situation coming up where I could practice this"}]'::jsonb, array['dialectics', 'core DBT', 'interpersonal effectiveness']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('skills-chain-substitution-plan', 'Skills Chain Substitution Plan', 'dbt'::resource_kind, 'Takes a chain analysis one step further by planning a skill to swap in at the weakest link.', 'Turn an already-completed chain analysis into a concrete plan for next time.', array['Adults', 'Teens']::text[], '20 minutes', 'Starting from a chain the client has already mapped, find the single link where a different choice would have changed the outcome most, then attach a specific skill to that exact link rather than a vague intention to do better. Rehearse the substitution out loud before the client leaves session. Revisit after the next similar chain to see whether the substitution held.', '[{"id": "f0", "type": "textarea", "label": "The chain I already mapped: situation, links, outcome"}, {"id": "f1", "type": "textarea", "label": "The weakest link, where a different choice matters most"}, {"id": "f2", "type": "textarea", "label": "The skill I will substitute at that link"}, {"id": "f3", "type": "textarea", "label": "What might get in the way of using it"}, {"id": "f4", "type": "textarea", "label": "How I will remind myself in the moment"}]'::jsonb, array['chain analysis', 'core DBT', 'skills']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('difficult-topic-pre-talk-agreement', 'Difficult Topic Pre-Talk Agreement', 'couples'::resource_kind, 'Sets ground rules together before a hard conversation instead of discovering them mid-fight.', 'Give both partners a shared structure to fall back on when a topic gets heated.', array['Couples']::text[], '15 minutes', 'Before raising the actual topic, have both partners agree on how long the conversation will run, a signal either can use to pause, and what happens if it gets too heated to continue. Doing this while calm means neither partner is negotiating ground rules in the middle of a spike. Revisit the agreement afterward and adjust anything that did not hold.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need to feel safe in this conversation"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need to feel safe in this conversation"}, {"id": "f2", "type": "textarea", "label": "How long we agree to talk before checking in"}, {"id": "f3", "type": "textarea", "label": "Our pause signal, if either of us needs one"}, {"id": "f4", "type": "textarea", "label": "What we will do if it gets too heated"}, {"id": "f5", "type": "textarea", "label": "What we agreed afterward"}]'::jsonb, array['communication', 'conflict']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('solo-time-and-we-time-balance-sheet', 'Solo Time and We Time Balance Sheet', 'couples'::resource_kind, 'Maps how much time each partner gets alone against time spent together, and where the balance feels off.', 'Make an unspoken imbalance between independence and togetherness visible and negotiable.', array['Couples']::text[], '20 minutes', 'Have each partner estimate their current solo time and couple time in an average week, then rate whether each feels like enough, too much, or too little. Mismatches here are common and rarely about wanting less of the other person; often one partner recharges alone and the other recharges together. Use the sheet to negotiate a small, concrete adjustment rather than a full overhaul.', '[{"id": "f0", "type": "textarea", "label": "Partner A: solo time in an average week, and how it feels"}, {"id": "f1", "type": "textarea", "label": "Partner B: solo time in an average week, and how it feels"}, {"id": "f2", "type": "textarea", "label": "Partner A: couple time in an average week, and how it feels"}, {"id": "f3", "type": "textarea", "label": "Partner B: couple time in an average week, and how it feels"}, {"id": "f4", "type": "textarea", "label": "One adjustment we want to try"}]'::jsonb, array['connection', 'routines']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('how-i-like-to-be-supported-sheet', 'How I Like to Be Supported Sheet', 'couples'::resource_kind, 'Has each partner describe what actually helps when they are struggling, instead of guessing.', 'Replace guesswork with each partner''s own instructions for being supported well.', array['Couples']::text[], '20 minutes', 'Ask each partner to think of a recent hard day and describe what kind of support they actually wanted, whether that was advice, quiet company, physical comfort, or space. Partners often default to giving the kind of support they themselves would want, which can miss the mark. Trade sheets and ask one clarifying question each before ending the session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I actually want when I am struggling"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help, even if well-intentioned"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I actually want when I am struggling"}, {"id": "f3", "type": "textarea", "label": "Partner B: what does not help, even if well-intentioned"}, {"id": "f4", "type": "textarea", "label": "One question I have after reading my partner''s sheet"}]'::jsonb, array['support', 'communication']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('re-connection-after-distance-plan', 'Re-Connection After Distance Plan', 'couples'::resource_kind, 'Plans a deliberate way back to closeness after a stretch of feeling distant, without assigning blame.', 'Give a couple a path back to connection that does not start with relitigating who caused the distance.', array['Couples']::text[], '30 minutes', 'Have both partners name what the distance has actually looked like day to day, then skip straight to what a small return to closeness could look like this week: a ritual, a touch point, a shared activity. Keep the focus forward; there will be time to process the cause later if it is still needed. Set one small, specific step each partner is willing to take first.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what the distance has looked like for me"}, {"id": "f1", "type": "textarea", "label": "Partner B: what the distance has looked like for me"}, {"id": "f2", "type": "textarea", "label": "A small way back to closeness we could both agree to"}, {"id": "f3", "type": "textarea", "label": "Partner A: one step I am willing to take first"}, {"id": "f4", "type": "textarea", "label": "Partner B: one step I am willing to take first"}]'::jsonb, array['connection', 'repair']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('shared-household-vision-conversation', 'Shared Household Vision Conversation', 'couples'::resource_kind, 'Has partners describe the home and routine they each picture, then find the overlap.', 'Surface mismatched pictures of daily life before they turn into ongoing friction.', array['Couples']::text[], '30 minutes', 'Ask each partner to describe, in detail, what an ordinary weekday and weekend look like in their ideal picture of the household, then compare the two descriptions side by side. Differences are often about pace and order rather than values, which makes them easier to negotiate once named. End with one small change either partner is willing to try toward the shared picture.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my picture of an ordinary weekday"}, {"id": "f1", "type": "textarea", "label": "Partner B: my picture of an ordinary weekday"}, {"id": "f2", "type": "textarea", "label": "Where our pictures overlap"}, {"id": "f3", "type": "textarea", "label": "Where they differ most"}, {"id": "f4", "type": "textarea", "label": "One change either of us is willing to try"}]'::jsonb, array['routines', 'communication']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('mistake-monster-craft', 'Mistake Monster Craft', 'kids'::resource_kind, 'A child builds a friendly monster that eats mistakes and turns them into something learned.', 'Give a child a playful way to separate a mistake from being a bad kid.', array['Children']::text[], '25 minutes', 'The parent helps the child build a simple monster from paper or a box with an opening for a mouth, then the two of them write small mistakes on slips of paper and feed them to the monster, saying out loud one thing the mistake taught. Keep the monster somewhere visible so a real mistake later in the week has somewhere to go right away. The parent naming their own mistakes for the monster helps too.', '[{"id": "f0", "type": "textarea", "label": "A mistake I want to feed the monster"}, {"id": "f1", "type": "textarea", "label": "What it taught me"}, {"id": "f2", "type": "textarea", "label": "How I felt before feeding it to the monster"}, {"id": "f3", "type": "textarea", "label": "How I feel after"}]'::jsonb, array['children', 'self-esteem', 'play']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('team-player-puzzle-build', 'Team Player Puzzle Build', 'kids'::resource_kind, 'A child and parent build a puzzle together, then talk about what teamwork felt like.', 'Practice turn-taking and cooperation in a low-stakes, hands-on activity.', array['Children']::text[], '25 minutes', 'The parent and child pick a puzzle sized for the child''s patience and build it together, taking visible turns and narrating out loud when a piece does not fit the first time. Afterward, ask what was easy about working together and what was hard, keeping the debrief short and light. This works well as a repeatable weekly activity rather than a one-time exercise.', '[{"id": "f0", "type": "textarea", "label": "What was fun about building this together"}, {"id": "f1", "type": "textarea", "label": "A piece that was tricky to find"}, {"id": "f2", "type": "textarea", "label": "How I felt when a piece did not fit"}, {"id": "f3", "type": "textarea", "label": "What working together was like"}]'::jsonb, array['children', 'play', 'social skills']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('kindness-chain-craft', 'Kindness Chain Craft', 'kids'::resource_kind, 'A child adds a paper link to a growing chain each time they notice an act of kindness.', 'Build a child''s habit of noticing kindness, given and received, over time.', array['Children']::text[], '20 minutes to start, then ongoing', 'Give the child strips of colored paper and have them add a link, with a word or two about what happened, whenever they do something kind or notice someone else do so. Hang the growing chain somewhere visible so progress is easy to see. At the end of each week, the parent and child read through the chain together before deciding whether to keep it going or start a new one.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I did today"}, {"id": "f1", "type": "textarea", "label": "A kind thing I noticed someone else do"}, {"id": "f2", "type": "textarea", "label": "How adding a link makes me feel"}, {"id": "f3", "type": "textarea", "label": "How long I want the chain to get"}]'::jsonb, array['children', 'kindness', 'play']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('growth-mindset-garden-craft', 'Growth Mindset Garden Craft', 'kids'::resource_kind, 'A child plants paper flowers that grow each time they try something hard, whether or not it works.', 'Teach a child that effort on a hard thing counts, separate from the result.', array['Children']::text[], '25 minutes', 'The child draws or cuts out a paper flower for a garden poster each time they try something that felt hard, whatever the outcome, and the parent writes a short note of what was attempted next to it. A flower for an attempt that did not work out yet belongs in the garden just as much as one for a success. Look at the growing garden together at the end of the week and notice how full it got.', '[{"id": "f0", "type": "textarea", "label": "A hard thing I tried this week"}, {"id": "f1", "type": "textarea", "label": "How it went"}, {"id": "f2", "type": "textarea", "label": "What I want to try next"}, {"id": "f3", "type": "textarea", "label": "How my garden is growing"}]'::jsonb, array['children', 'growth mindset', 'play']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('listening-ears-headband-craft', 'Listening Ears Headband Craft', 'kids'::resource_kind, 'A child decorates a headband with big paper ears to practice noticing what good listening feels like.', 'Make the abstract skill of listening something a child can put on and practice.', array['Children']::text[], '20 minutes', 'The child decorates a simple headband with oversized paper ears, then wears it during a short listening game where the parent tells a brief story and the child repeats back one detail. Talk about what good listening looks like in the body: eyes, stillness, not planning what to say next. Use the headband again during a moment the child is having trouble listening, as a playful reset rather than a correction.', '[{"id": "f0", "type": "textarea", "label": "A detail I remembered from the story"}, {"id": "f1", "type": "textarea", "label": "What my body was doing while I listened well"}, {"id": "f2", "type": "textarea", "label": "What made listening harder at other times"}, {"id": "f3", "type": "textarea", "label": "When I want to wear my listening ears again"}]'::jsonb, array['children', 'listening', 'play']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('common-ground-bingo', 'Common Ground Bingo', 'game'::resource_kind, 'A bingo card of everyday experiences group members fill in by finding others who share them.', 'Build quick connection in a group by surfacing shared, ordinary experience.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Give each member a bingo card of common experiences, moods and preferences, then have them mingle to find a different group member for each square who shares it, collecting a signature. This works well as an opening exercise before a group dives into harder material, since it lowers the temperature in the room. Debrief by asking what surprised people about what they had in common.', '[{"id": "f0", "type": "textarea", "label": "A square that was easy to fill"}, {"id": "f1", "type": "textarea", "label": "A square that was hard to fill"}, {"id": "f2", "type": "textarea", "label": "A surprising thing I had in common with someone"}, {"id": "f3", "type": "textarea", "label": "How the room felt afterward"}]'::jsonb, array['group', 'icebreaker', 'connection']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('scenario-debate-circle', 'Scenario Debate Circle', 'game'::resource_kind, 'The group debates short everyday dilemma scenarios in turns, then compares how differently people would respond.', 'Practice hearing a range of reasonable responses instead of assuming there is one right answer.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Read a brief, low-stakes dilemma to the group, have members take turns stating what they would do and why, then open a short discussion of the differences. Keep the scenarios ordinary rather than clinical, since the goal is flexible thinking and perspective-taking. Rotate who reads the next scenario to keep engagement high.', '[{"id": "f0", "type": "textarea", "label": "The scenario we discussed"}, {"id": "f1", "type": "textarea", "label": "What I said I would do"}, {"id": "f2", "type": "textarea", "label": "A different response that stood out to me"}, {"id": "f3", "type": "textarea", "label": "What I noticed about how differently people think"}]'::jsonb, array['group', 'play', 'flexibility']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('pass-the-story-building-game', 'Pass the Story Building Game', 'game'::resource_kind, 'The group builds a story one sentence at a time, passing it around the circle.', 'Build group cohesion and creative flexibility through low-stakes shared play.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'One person starts a story with a single sentence, and each member adds one more sentence in turn, with no planning allowed beyond what came before. Encourage members to accept whatever the story becomes rather than steering it toward their own idea. Read the finished story back at the end and let the group enjoy how strange it turned out.', '[{"id": "f0", "type": "textarea", "label": "The sentence I added"}, {"id": "f1", "type": "textarea", "label": "What surprised me about where the story went"}, {"id": "f2", "type": "textarea", "label": "What it was like to accept someone else''s direction"}, {"id": "f3", "type": "textarea", "label": "What I would have added if it were only my story"}]'::jsonb, array['group', 'play', 'creativity']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('strengths-scavenger-hunt', 'Strengths Scavenger Hunt', 'game'::resource_kind, 'Group members hunt for evidence of a listed strength in each other over the course of the session.', 'Give the group practice noticing and naming strengths, including their own.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Hand out a list of strengths, then have members quietly watch for a moment during the session when another member shows one of them, jotting down who and what happened. Read the findings aloud at the end so each person hears a specific example of a strength others noticed in them. This tends to land better than a general compliment because it points to something that actually happened.', '[{"id": "f0", "type": "textarea", "label": "A strength I noticed in someone else, and what happened"}, {"id": "f1", "type": "textarea", "label": "A strength someone noticed in me"}, {"id": "f2", "type": "textarea", "label": "How it felt to hear a specific example"}, {"id": "f3", "type": "textarea", "label": "A strength I want to notice in myself more often"}]'::jsonb, array['strengths', 'self-esteem', 'group']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('number-line-feelings-game', 'Number Line Feelings Game', 'game'::resource_kind, 'Members physically move along a taped number line to show how strongly they feel about a called-out topic.', 'Make emotional intensity visible and easy to compare across a group.', array['Groups', 'Children', 'Teens']::text[], '15 minutes', 'Tape a number line from zero to ten on the floor, call out a topic or situation, and have members stand at the point that matches how strongly they feel about it, then briefly say why. Seeing the spread across the group normalizes that people land in different places on the same topic. This works well as a quick check-in at the start or end of a group session.', '[{"id": "f0", "type": "textarea", "label": "The topic that was called"}, {"id": "f1", "type": "textarea", "label": "Where I stood on the line"}, {"id": "f2", "type": "textarea", "label": "Why I stood there"}, {"id": "f3", "type": "textarea", "label": "What I noticed about where others stood"}]'::jsonb, array['group', 'play', 'emotion identification']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('anniversary-dates-coping-plan', 'Anniversary Dates Coping Plan', 'worksheet'::resource_kind, 'Prepares a client for the days each year an anniversary date tends to bring symptoms back up.', 'Have a plan ready before an anniversary date arrives, not scrambling once it has started.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client whether certain dates, an event date, a season, a holiday, tend to bring symptoms up, then plan in advance what support, workload and self-care will look like around that date this year. Building the plan weeks ahead, while calm, works better than trying to plan during the date itself. Include 988, call or text, on the plan for the worst hours.', '[{"id": "f0", "type": "textarea", "label": "A date or time of year that tends to be hard"}, {"id": "f1", "type": "textarea", "label": "What usually shows up around that date"}, {"id": "f2", "type": "textarea", "label": "Support I want lined up in advance"}, {"id": "f3", "type": "textarea", "label": "What I will lighten or move on my schedule that week"}, {"id": "f4", "type": "textarea", "label": "A grounding skill I want ready"}, {"id": "f5", "type": "textarea", "label": "988, call or text, if it gets to be too much"}]'::jsonb, array['PTSD and trauma', 'safety planning', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('hypervigilance-pattern-log', 'Hypervigilance Pattern Log', 'cbt'::resource_kind, 'Logs what sets off a client''s scanning for danger and what actually helps it settle.', 'Show the client their own hypervigilance pattern instead of it feeling constant and unexplained.', array['Adults', 'Teens']::text[], 'One week', 'Have the client note moments they notice themselves scanning a room, over-checking, or bracing for something to go wrong, along with what was happening just before and what helped it ease. Patterns often emerge around specific settings, sounds, or people rather than being truly constant. Use the log to plan where extra grounding support might help most.', '[{"id": "f0", "type": "textarea", "label": "A moment I noticed myself scanning or bracing"}, {"id": "f1", "type": "textarea", "label": "What was happening just before"}, {"id": "f2", "type": "textarea", "label": "How intense it got, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What helped it ease"}, {"id": "f4", "type": "textarea", "label": "A pattern I am starting to notice"}]'::jsonb, array['PTSD and trauma', 'monitoring', 'core CBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('steady-ground-values-check', 'Steady Ground Values Check', 'act'::resource_kind, 'Chooses one small values-based action for the week that does not require discussing the trauma itself.', 'Keep the client''s life moving toward what matters while stabilization work continues.', array['Adults', 'Teens']::text[], '15 minutes', 'Trauma work does not have to wait for a values check-in; ask what matters to the client right now and what one small, steadying action toward it would look like this week, without needing to process or recount anything. Keep the scope small and doable. This is deliberately separate from any processing work and can run alongside it at the client''s pace.', '[{"id": "f0", "type": "textarea", "label": "Something that still matters to me right now"}, {"id": "f1", "type": "textarea", "label": "One small step toward it this week"}, {"id": "f2", "type": "textarea", "label": "What might make that step hard"}, {"id": "f3", "type": "textarea", "label": "What would help it feel more doable"}, {"id": "f4", "type": "textarea", "label": "How I want to feel at the end of the week"}]'::jsonb, array['PTSD and trauma', 'values', 'core ACT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('family-calm-signal-craft', 'Family Calm Signal Craft', 'kids'::resource_kind, 'A child and parent create a private hand signal for when the child feels overwhelmed or unsafe.', 'Give a child a fast, wordless way to ask a parent for help in the moment.', array['Children']::text[], '20 minutes', 'The parent and child decide together on a simple hand signal or word the child can use anytime, anywhere, to mean I need you right now, then practice it a few times in a calm moment so it is ready when needed. Decorate a small card together as a reminder of what the signal means. If a child discloses anything during this activity, the clinician follows the practice''s reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Our signal"}, {"id": "f1", "type": "textarea", "label": "What it means"}, {"id": "f2", "type": "textarea", "label": "A time I practiced using it"}, {"id": "f3", "type": "textarea", "label": "How my grown-up responded"}, {"id": "f4", "type": "textarea", "label": "When I might use it"}]'::jsonb, array['PTSD and trauma', 'children', 'safety']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('partner-debrief-after-a-hard-day-sheet', 'Partner Debrief After a Hard Day Sheet', 'couples'::resource_kind, 'A short structured check-in for after a day symptoms flared, without asking for the trauma story.', 'Give partners a way to support each other after a hard day that stays on the supporting side.', array['Couples']::text[], '15 minutes', 'After a day that was harder than usual, have the affected partner share only what they need right now, not what happened or why, while the other partner listens and offers concrete options rather than questions. This keeps the conversation supportive without asking either partner to revisit content that belongs in session. Agree in advance on a phrase that signals the debrief is done.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what kind of support I need right now"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can offer right now"}, {"id": "f2", "type": "textarea", "label": "What helped tonight"}, {"id": "f3", "type": "textarea", "label": "What we will use as our debrief-is-done phrase"}, {"id": "f4", "type": "textarea", "label": "What Partner B wants to check on tomorrow"}]'::jsonb, array['PTSD and trauma', 'support', 'couples']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('anxiety-distress-tolerance-menu', 'Anxiety Distress Tolerance Menu', 'dbt'::resource_kind, 'Sorts a client''s distress tolerance skills by how fast they work when anxiety spikes.', 'Give the client a ranked menu instead of guessing which skill to reach for first.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client list the distress tolerance skills that have worked before, then rank them by how fast each one actually kicks in during a spike, not how good they sound. A fast, imperfect skill used immediately usually beats a slower, better one used too late. Test the top-ranked skill at a lower anxiety level first so it is rehearsed before it is needed.', '[{"id": "f0", "type": "textarea", "label": "A distress tolerance skill that has worked before"}, {"id": "f1", "type": "textarea", "label": "How fast it usually kicks in"}, {"id": "f2", "type": "textarea", "label": "Another skill, and its speed"}, {"id": "f3", "type": "textarea", "label": "My fastest option, ranked first"}, {"id": "f4", "type": "textarea", "label": "When I tested it at a lower level"}]'::jsonb, array['anxiety', 'distress tolerance', 'core DBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('anxiety-alphabet-game', 'Anxiety Alphabet Game', 'game'::resource_kind, 'Group races through the alphabet naming a coping skill or calming word for each letter.', 'Build a large, quick-access vocabulary of coping options through playful repetition.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Going around the circle, each member names a coping skill or calming word starting with the next letter of the alphabet, keeping the pace light and forgiving mistakes with a laugh rather than a restart. The playful pressure mimics a small amount of performance pressure in a safe setting while building a long list of options. Debrief which idea from the round the group wants to actually try this week.', '[{"id": "f0", "type": "textarea", "label": "A coping idea I contributed"}, {"id": "f1", "type": "textarea", "label": "An idea from someone else that I want to try"}, {"id": "f2", "type": "textarea", "label": "How the pressure of the game felt"}, {"id": "f3", "type": "textarea", "label": "What I noticed about that feeling passing"}]'::jsonb, array['anxiety', 'coping skills', 'group']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('anxious-partner-support-plan', 'Anxious Partner Support Plan', 'couples'::resource_kind, 'Agrees in advance how a partner can help when anxiety spikes, without accidentally reinforcing avoidance.', 'Give both partners a script for support that helps in the moment without feeding the anxiety cycle long-term.', array['Couples']::text[], '20 minutes', 'Ask the anxious partner what genuinely helps in the moment, a specific phrase, a few minutes of quiet, a grounding cue, versus what a well-meaning partner does that ends up reinforcing avoidance, such as taking over a task the client is capable of doing anxious. Agree on a short list each partner can actually follow. Revisit the plan as it gets tested in real situations.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what actually helps when my anxiety spikes"}, {"id": "f1", "type": "textarea", "label": "Partner A: what unintentionally reinforces my avoidance"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I can do instead"}, {"id": "f3", "type": "textarea", "label": "A recent moment we want to try this differently"}, {"id": "f4", "type": "textarea", "label": "What we agreed to going forward"}]'::jsonb, array['anxiety', 'support', 'couples']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('anxious-thoughts-weather-forecast', 'Anxious Thoughts Weather Forecast', 'act'::resource_kind, 'Treats an anxious prediction like a weather forecast that might or might not hold, rather than a fact.', 'Loosen the grip of a feared prediction by relating to it as one possible forecast, not a guarantee.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to state their anxious prediction the way a weather forecaster would: a chance of something happening, not a certainty. Notice how often a forecast of rain still leaves room for a dry day, and how the client can carry an umbrella, a coping plan, without canceling the day over a percentage. Practice restating a few current worries as forecasts rather than facts.', '[{"id": "f0", "type": "textarea", "label": "My anxious prediction"}, {"id": "f1", "type": "textarea", "label": "Restated as a forecast: a chance of..."}, {"id": "f2", "type": "textarea", "label": "My umbrella, a coping plan just in case"}, {"id": "f3", "type": "textarea", "label": "What I would do today even with this forecast"}, {"id": "f4", "type": "textarea", "label": "How treating it as a forecast changes how it feels"}]'::jsonb, array['anxiety', 'defusion', 'core ACT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('anxiety-trigger-and-ease-map', 'Anxiety Trigger and Ease Map', 'worksheet'::resource_kind, 'Maps the situations that reliably raise a client''s anxiety against what has reliably brought it back down.', 'Give the client a two-sided reference of what raises and what eases anxiety, built from their own history.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client list several situations that reliably raise anxiety on one side and, on the other, specific things, people, places, actions, that have reliably brought it back down before. The point is not to avoid every trigger but to know in advance what tends to help once anxiety is already up. Keep both lists growing as new examples come up between sessions.', '[{"id": "f0", "type": "textarea", "label": "A situation that reliably raises my anxiety"}, {"id": "f1", "type": "textarea", "label": "Another one"}, {"id": "f2", "type": "textarea", "label": "Something that has reliably eased it before"}, {"id": "f3", "type": "textarea", "label": "Another thing that helps"}, {"id": "f4", "type": "textarea", "label": "A trigger and an ease strategy I want to pair together"}]'::jsonb, array['anxiety', 'self-monitoring', 'coping skills']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('small-mastery-credit-log', 'Small Mastery Credit Log', 'dbt'::resource_kind, 'Logs small tasks completed on a low-mood day so accomplishment does not get erased by the mood.', 'Keep a running record of mastery that depression''s memory tends to discount.', array['Adults', 'Teens']::text[], 'Daily, a few minutes', 'On a low-mood day, have the client log even small completed tasks, since depression often erases the memory of having done anything by evening. Rate each one for how hard it actually was to do given the day''s energy, not how impressive it looks from the outside. Review the week''s log together, since clients are often surprised by how much is on it.', '[{"id": "f0", "type": "textarea", "label": "Something I completed today, even something small"}, {"id": "f1", "type": "textarea", "label": "How hard it was given today''s energy, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What almost stopped me from doing it"}, {"id": "f3", "type": "textarea", "label": "What I notice looking back at the week''s log"}]'::jsonb, array['depression', 'core DBT', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('depression-energy-investment-sheet', 'Depression Energy Investment Sheet', 'worksheet'::resource_kind, 'Compares where a client''s limited energy currently goes against where investing it would help mood most.', 'Help the client spend a small energy budget where it will do the most good, not just what is easiest.', array['Adults', 'Teens']::text[], '20 minutes', 'List where the client''s energy currently goes across a typical day, then rate each activity for how much it actually lifts mood versus how much it just fills time or drains further. Depression often steers energy toward passive activities that feel easier but do not help, so the comparison itself is often the useful part. Choose one low-cost, higher-payoff activity to try investing in this week.', '[{"id": "f0", "type": "textarea", "label": "Where my energy currently goes in a typical day"}, {"id": "f1", "type": "textarea", "label": "How much each one lifts my mood, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "An activity that costs little but tends to help"}, {"id": "f3", "type": "textarea", "label": "One I want to invest more energy in this week"}]'::jsonb, array['depression', 'behavioral activation', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('morning-motivation-sticker-choice', 'Morning Motivation Sticker Choice', 'kids'::resource_kind, 'A child picks one small activity from a menu each low-energy morning to build a little momentum.', 'Give a child, and parent, a low-effort way to start a hard morning instead of nothing at all.', array['Children']::text[], '10 minutes each morning', 'Together, the parent and child build a short menu of easy, appealing options, a song, a stretch, a favorite cereal bowl chosen specially, for mornings that feel heavy, then the child picks just one to do before anything else. The goal is momentum, not a full routine, so keep the bar low and celebrate the pick itself, not just finishing it. Adjust the menu together every couple of weeks.', '[{"id": "f0", "type": "textarea", "label": "What I picked this morning"}, {"id": "f1", "type": "textarea", "label": "How I felt before I started"}, {"id": "f2", "type": "textarea", "label": "How I felt after"}, {"id": "f3", "type": "textarea", "label": "Something I want to add to the menu"}]'::jsonb, array['depression', 'children', 'routines']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('yes-but-catch-sheet', 'Yes But Catch Sheet', 'cbt'::resource_kind, 'Catches the moment a client discounts a genuine positive with a yes but and rewrites it plainly.', 'Interrupt the automatic discounting that keeps positives from actually registering.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client for a recent positive moment, then notice whether a yes but followed it in their own mind, discounting luck, timing, or someone else''s help. Write the positive again without the but, as a plain, standalone fact. This does not have to feel true right away; the point is to practice noticing the discount as it happens.', '[{"id": "f0", "type": "textarea", "label": "A positive moment from this week"}, {"id": "f1", "type": "textarea", "label": "The yes but that followed it in my mind"}, {"id": "f2", "type": "textarea", "label": "The positive, rewritten without the but"}, {"id": "f3", "type": "textarea", "label": "How it feels to leave it standing on its own"}]'::jsonb, array['depression', 'thinking traps', 'core CBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('low-mood-day-check-in-script', 'Low-Mood Day Check-In Script', 'couples'::resource_kind, 'A short script partners use on a low-mood day to check in without either one needing to fix anything.', 'Give partners words to reach for on a hard day instead of silence or over-managing.', array['Couples']::text[], '5 minutes', 'On a day the depressed partner is struggling, have the other partner ask a short, fixed set of questions: how the day has been, what would help right now, and whether they want company or space. The depressed partner answers as honestly as they can, even I don''t know. Using the same script each time takes the guesswork out of a hard moment for both partners.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how the day has been"}, {"id": "f1", "type": "textarea", "label": "Partner A: what would help right now"}, {"id": "f2", "type": "textarea", "label": "Partner A: company or space right now"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I heard and what I will do"}]'::jsonb, array['depression', 'support', 'couples']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('task-card-shuffle-game', 'Task Card Shuffle Game', 'game'::resource_kind, 'Turns a stalled task list into a shuffled deck the client draws from one card at a time.', 'Lower the activation energy of starting by removing the choice of what to do first.', array['Adults', 'Teens']::text[], 'Ongoing, a few minutes to set up', 'Write each pending task on its own card, shuffle the deck, and have the client commit to working on whatever card comes up next for a short set time before drawing again. Removing the decision of what to do first often removes the biggest barrier to starting anything at all. Let the client discard a card that genuinely does not belong on the list rather than forcing every task through.', '[{"id": "f0", "type": "textarea", "label": "Tasks I put on cards this round"}, {"id": "f1", "type": "textarea", "label": "The card I drew first"}, {"id": "f2", "type": "textarea", "label": "How starting felt once the choice was made for me"}, {"id": "f3", "type": "textarea", "label": "A card I discarded, and why"}]'::jsonb, array['ADHD', 'task initiation', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('adhd-reminder-system-agreement', 'ADHD Reminder System Agreement', 'couples'::resource_kind, 'Agrees how one partner will remind the other about a task without it landing as nagging.', 'Replace an unspoken, resentment-building reminder pattern with one both partners actually agreed to.', array['Couples']::text[], '20 minutes', 'Ask the partner who forgets what kind of reminder actually helps, a text, a note, a specific time of day, and ask the partner who reminds what makes reminding feel exhausting or thankless. Agree on a specific method and a specific number of reminders before it becomes the forgetting partner''s job to catch up on their own. Revisit after a week of trying it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what kind of reminder actually helps me"}, {"id": "f1", "type": "textarea", "label": "Partner A: what makes a reminder land badly"}, {"id": "f2", "type": "textarea", "label": "Partner B: what makes reminding feel exhausting"}, {"id": "f3", "type": "textarea", "label": "The method we agreed to"}, {"id": "f4", "type": "textarea", "label": "How many reminders before it is on me to catch up"}]'::jsonb, array['ADHD', 'communication', 'couples']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('environment-friction-audit', 'Environment Friction Audit', 'worksheet'::resource_kind, 'Walks through a client''s physical spaces looking for small frictions that make a routine task harder to start.', 'Redesign the environment instead of relying on willpower to overcome an avoidable obstacle.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through a task the client keeps avoiding and ask what small physical friction sits between them and starting: a closed cabinet, a missing charger, an item not in sight. ADHD makes out-of-sight genuinely out-of-mind, so small environmental changes often outperform reminders. Pick one friction point to remove this week and one to test.', '[{"id": "f0", "type": "textarea", "label": "A task I keep avoiding"}, {"id": "f1", "type": "textarea", "label": "What physically sits between me and starting it"}, {"id": "f2", "type": "textarea", "label": "A small change that would remove that friction"}, {"id": "f3", "type": "textarea", "label": "What I will try this week"}]'::jsonb, array['ADHD', 'environment', 'task initiation']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('now-vs-later-cost-sheet', 'Now vs Later Cost Sheet', 'cbt'::resource_kind, 'Weighs the small cost of starting a task now against the larger cost of it piling up later.', 'Make the invisible future cost of avoidance visible enough to counter present bias.', array['Adults', 'Teens']::text[], '10 minutes', 'Before deciding whether to start a task, have the client rate how unpleasant starting feels right now, then estimate how much worse the task, or its consequences, will feel if left for another day or week. ADHD often weighs the near cost far more heavily than the distant one, and writing both numbers side by side helps correct for that. Use it as a quick check before a task gets pushed off again.', '[{"id": "f0", "type": "textarea", "label": "The task"}, {"id": "f1", "type": "textarea", "label": "How unpleasant starting feels right now, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "How much worse it gets if I wait a day"}, {"id": "f3", "type": "textarea", "label": "How much worse if I wait a week"}, {"id": "f4", "type": "textarea", "label": "What I decide to do"}]'::jsonb, array['ADHD', 'core CBT', 'decision-making']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('movement-break-menu-craft', 'Movement Break Menu Craft', 'kids'::resource_kind, 'A child builds a spinner or menu of short movement breaks to use between tasks that need focus.', 'Give a child an approved way to move that supports focus instead of interrupting it.', array['Children']::text[], '20 minutes', 'The parent and child decorate a simple spinner or card menu of short movement options, like ten jumping jacks or a lap around the room, to use between homework problems or chores. Agree in advance on how long a break lasts and what signals it is time to return to the task. Movement breaks used this way tend to support focus rather than derail it, especially when they are built in rather than fought over.', '[{"id": "f0", "type": "textarea", "label": "The movement break I picked"}, {"id": "f1", "type": "textarea", "label": "How I felt before the break"}, {"id": "f2", "type": "textarea", "label": "How I felt after"}, {"id": "f3", "type": "textarea", "label": "How the return to the task went"}]'::jsonb, array['ADHD', 'children', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('supporting-without-enabling-conversation', 'Supporting Without Enabling Conversation', 'couples'::resource_kind, 'Helps partners tell the difference between supportive help and covering for substance use.', 'Give both partners language to negotiate support that does not slide into covering.', array['Couples']::text[], '25 minutes', 'Ask the non-using partner to list ways they currently help, then sort each one into supportive, helps recovery, or covering, removes a natural consequence of substance use. This is often uncomfortable, since covering usually comes from care, not carelessness. Agree together on one or two changes and how the supporting partner will take care of themselves through the shift.', '[{"id": "f0", "type": "textarea", "label": "Partner A: ways I currently help"}, {"id": "f1", "type": "textarea", "label": "Which of these feel supportive"}, {"id": "f2", "type": "textarea", "label": "Which of these might be covering"}, {"id": "f3", "type": "textarea", "label": "One change we want to try"}, {"id": "f4", "type": "textarea", "label": "How Partner A will take care of themselves through this"}]'::jsonb, array['addiction', 'support', 'couples']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('feelings-about-a-parents-recovery-drawing', 'Feelings About a Parent''s Recovery Drawing', 'kids'::resource_kind, 'A child draws their feelings about changes at home during a parent''s recovery, with the parent alongside.', 'Give a child a simple, safe way to express feelings about a confusing change at home.', array['Children']::text[], '20 minutes', 'The parent sits with the child while they draw how things have felt at home lately, using color rather than words if that is easier, and the parent listens without correcting or over-explaining. Keep the language simple and age-appropriate: a grown-up has been working on staying healthy, not clinical detail. This works best paired with guidance from the child''s own therapist about what to say.', '[{"id": "f0", "type": "textarea", "label": "A color for how home has felt lately"}, {"id": "f1", "type": "textarea", "label": "Something that has felt confusing"}, {"id": "f2", "type": "textarea", "label": "A question I have"}, {"id": "f3", "type": "textarea", "label": "Something that has felt good lately"}]'::jsonb, array['addiction', 'children', 'family']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('urge-wave-timing-card', 'Urge Wave Timing Card', 'dbt'::resource_kind, 'Times how long an urge actually lasts from start to fade, building evidence that it will pass.', 'Give the client their own data that an urge has a shape and an end, not just a peak.', array['Adults', 'Teens']::text[], 'In the moment, ongoing', 'When an urge starts, have the client note the start time and intensity, then check back every few minutes until it clearly fades, logging how long the whole wave took. Urges almost always pass faster than they feel like they will in the moment, and a client''s own timed log is more convincing than being told that in the abstract. Review several timed urges together to spot the pattern.', '[{"id": "f0", "type": "textarea", "label": "When the urge started"}, {"id": "f1", "type": "textarea", "label": "Starting intensity, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Intensity checked every few minutes"}, {"id": "f3", "type": "textarea", "label": "When it clearly faded"}, {"id": "f4", "type": "textarea", "label": "Total time from start to fade"}]'::jsonb, array['addiction', 'urges', 'distress tolerance']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('urge-or-boredom-sorting-game', 'Urge or Boredom Sorting Game', 'game'::resource_kind, 'A quick sorting game that helps a client tell a real urge apart from boredom or habit.', 'Build the client''s speed at correctly naming what is actually driving the moment.', array['Groups', 'Adults', 'Teens']::text[], '15 minutes', 'Read short scenario cards describing a moment, idle hands, a stressful call, a familiar time of day, and have group members sort each one as more likely urge, boredom, or habit, then discuss the differences out loud. Getting this distinction right matters because the useful response is different for each. Keep the tone light and collaborative.', '[{"id": "f0", "type": "textarea", "label": "A scenario we sorted"}, {"id": "f1", "type": "textarea", "label": "How I sorted it and why"}, {"id": "f2", "type": "textarea", "label": "A time this distinction would have helped me"}, {"id": "f3", "type": "textarea", "label": "What I would do differently knowing which one it was"}]'::jsonb, array['addiction', 'urges', 'group']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('substance-free-identity-inventory', 'Substance-Free Identity Inventory', 'worksheet'::resource_kind, 'Lists the parts of a client''s identity and daily life that exist apart from substance use.', 'Widen a client''s sense of self beyond the role substance use has taken up.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to list roles, interests and relationships that have nothing to do with substance use, even ones that feel small or rusty from disuse. Recovery can feel like losing an identity if substance use had taken up a lot of space, so this rebuilds a fuller picture to stand on. Pick one item on the list to reinvest in this month.', '[{"id": "f0", "type": "textarea", "label": "A role or relationship that exists apart from substance use"}, {"id": "f1", "type": "textarea", "label": "An interest that has gone rusty"}, {"id": "f2", "type": "textarea", "label": "What it would take to reconnect with it"}, {"id": "f3", "type": "textarea", "label": "One item I want to reinvest in this month"}]'::jsonb, array['addiction', 'values', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('anger-as-a-signal-practice', 'Anger as a Signal Practice', 'act'::resource_kind, 'Treats a flash of anger as a signal pointing toward a value being crossed, not just a feeling to suppress.', 'Redirect anger''s energy toward the value underneath it instead of only managing the reaction.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client what a recent flash of anger might be pointing to: a boundary, a fairness value, something that mattered being disregarded. This does not excuse how the anger got acted on, but it treats the feeling itself as useful information rather than purely a problem. Practice naming the value out loud the next time anger shows up, before deciding what to do about it.', '[{"id": "f0", "type": "textarea", "label": "A recent moment of anger"}, {"id": "f1", "type": "textarea", "label": "What value it might be pointing to"}, {"id": "f2", "type": "textarea", "label": "How I acted on it"}, {"id": "f3", "type": "textarea", "label": "What acting from the value, not just the anger, could look like"}, {"id": "f4", "type": "textarea", "label": "A phrase to help me name the value next time"}]'::jsonb, array['anger management', 'values', 'core ACT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('anger-vulnerability-factors-check', 'Anger Vulnerability Factors Check', 'dbt'::resource_kind, 'Checks the day''s sleep, stress and physical state that make anger flare faster than usual.', 'Catch the vulnerability factors that shorten a client''s fuse before the trigger even happens.', array['Adults', 'Teens']::text[], '10 minutes', 'Each day, have the client rate sleep, hunger, physical discomfort and general stress alongside how short their fuse felt. A short fuse is often explained more by the day''s vulnerability factors than by whatever finally triggered the blowup. Use the pattern to plan which factor to protect first on a day anger is likely to run high.', '[{"id": "f0", "type": "textarea", "label": "Sleep last night"}, {"id": "f1", "type": "textarea", "label": "Hunger or meals today"}, {"id": "f2", "type": "textarea", "label": "Physical discomfort today"}, {"id": "f3", "type": "textarea", "label": "General stress level today, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "How short my fuse felt"}]'::jsonb, array['anger management', 'self-monitoring', 'core DBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('anger-cost-ledger', 'Anger Cost Ledger', 'worksheet'::resource_kind, 'Tallies what a recent angry outburst actually cost against what the client hoped it would accomplish.', 'Make the real cost of an outburst visible enough to motivate trying something different.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client describe a recent outburst, what they hoped venting the anger would accomplish, and what it actually cost in time, relationships or trust afterward. The comparison is often lopsided in a way that surprises the client once it is written down plainly. Use the ledger to decide what a lower-cost response might look like next time.', '[{"id": "f0", "type": "textarea", "label": "The outburst"}, {"id": "f1", "type": "textarea", "label": "What I hoped it would accomplish"}, {"id": "f2", "type": "textarea", "label": "What it actually cost afterward"}, {"id": "f3", "type": "textarea", "label": "How the cost compares to what I hoped for"}, {"id": "f4", "type": "textarea", "label": "A lower-cost response I could try next time"}]'::jsonb, array['anger management', 'self-monitoring', 'decision-making']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('anger-weather-craft', 'Anger Weather Craft', 'kids'::resource_kind, 'A child builds a spinning weather wheel to show how their anger changes from storm to calm.', 'Give a child a concrete way to show that anger is a weather pattern that moves, not a permanent state.', array['Children']::text[], '25 minutes', 'The parent and child build a simple spinning wheel with weather pictures from calm to storm, and the child moves the pointer to show how angry they feel right now. Talk about what helped move the pointer back toward calm after a past storm. Keep the wheel somewhere the child can reach it and use it during an actual angry moment, not just in the craft session.', '[{"id": "f0", "type": "textarea", "label": "Where my pointer is right now"}, {"id": "f1", "type": "textarea", "label": "What got me to storm today, if anything"}, {"id": "f2", "type": "textarea", "label": "What helps move my pointer back toward calm"}, {"id": "f3", "type": "textarea", "label": "Where I want my pointer to be by bedtime"}]'::jsonb, array['anger management', 'children', 'play']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('cool-down-race-game', 'Cool Down Race Game', 'game'::resource_kind, 'A timed group game where members race to use a calming skill and lower their own rated intensity.', 'Turn practicing a calming skill into a friendly challenge instead of a chore.', array['Groups', 'Teens', 'Children']::text[], '15 minutes', 'Have members rate how keyed up they feel, then race against a timer to use a chosen calming skill, paced breathing, a stretch, counting, and rate themselves again at the end. Nobody actually loses; the game is really about noticing how fast a skill can shift the number even a little. Compare notes on which skill worked fastest for different people.', '[{"id": "f0", "type": "textarea", "label": "My rating before, 0 to 10"}, {"id": "f1", "type": "textarea", "label": "The skill I used"}, {"id": "f2", "type": "textarea", "label": "My rating after"}, {"id": "f3", "type": "textarea", "label": "What I noticed about how fast it worked"}]'::jsonb, array['anger management', 'group', 'coping skills']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('certainty-tolerance-log', 'Certainty Tolerance Log', 'worksheet'::resource_kind, 'Logs a moment a client resisted checking for certainty and tracks what actually happened afterward.', 'Build evidence that not knowing for sure is survivable, one logged moment at a time.', array['Adults', 'Teens']::text[], 'One week', 'When the urge to check or seek reassurance shows up, have the client note what they were uncertain about, whether they resisted checking, and what actually happened as a result. Most entries will show that uncertainty resolved on its own or simply stopped mattering. Review the week''s log together to build the pattern into something the client can point to.', '[{"id": "f0", "type": "textarea", "label": "What I was uncertain about"}, {"id": "f1", "type": "textarea", "label": "The urge to check or ask, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Whether I resisted"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I notice across this week''s entries"}]'::jsonb, array['OCD', 'uncertainty', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('reassurance-request-agreement', 'Reassurance Request Agreement', 'couples'::resource_kind, 'Agrees in advance how a partner will respond when asked for reassurance about an OCD worry.', 'Give both partners a planned response that supports without feeding the reassurance cycle.', array['Couples']::text[], '20 minutes', 'Reassurance from a partner usually calms an OCD worry for only a few minutes before it returns, often stronger, so agree together on a short, kind, consistent response the reassuring partner will use instead of answering the question directly. Practice the response together while calm. Revisit and adjust once it has been tried in a real moment.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a reassurance question I often ask"}, {"id": "f1", "type": "textarea", "label": "Partner B: what answering it usually leads to"}, {"id": "f2", "type": "textarea", "label": "The response we agreed to use instead"}, {"id": "f3", "type": "textarea", "label": "How it felt to try it"}, {"id": "f4", "type": "textarea", "label": "What we want to adjust"}]'::jsonb, array['OCD', 'family accommodation', 'couples']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('worry-bug-feeding-schedule-craft', 'Worry Bug Feeding Schedule Craft', 'kids'::resource_kind, 'A child sets specific times to check in with a worry instead of asking right away, using a visual timer.', 'Give a child practice delaying a checking or reassurance urge with a concrete, playful tool.', array['Children']::text[], '15 minutes to set up, then ongoing', 'The parent and child pick two or three set times a day to talk about worries together, and in between, the child draws or writes the worry on a card to hold until the next scheduled time instead of asking right away. Praise the delay itself, not whether the worry turned out to matter. Shorten the wait time gradually as the child gets more practice holding a worry.', '[{"id": "f0", "type": "textarea", "label": "A worry I held onto for later"}, {"id": "f1", "type": "textarea", "label": "How long I had to wait"}, {"id": "f2", "type": "textarea", "label": "How it felt to wait"}, {"id": "f3", "type": "textarea", "label": "What we talked about at check-in time"}]'::jsonb, array['OCD', 'children', 'play']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('uncertainty-roll-game', 'Uncertainty Roll Game', 'game'::resource_kind, 'Group members roll dice to decide small parts of an activity, practicing tolerance for an outcome they do not control.', 'Build comfort with uncertainty through low-stakes, playful repetition.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Use a die roll to decide small, harmless details of a group activity, such as speaking order or which topic comes next, and have members notice their reaction to not controlling the outcome. Debrief how the urge to control the small stuff showed up and how quickly it actually passed. Keep the stakes genuinely low so the exercise stays approachable rather than distressing.', '[{"id": "f0", "type": "textarea", "label": "What the roll decided"}, {"id": "f1", "type": "textarea", "label": "My reaction to not choosing"}, {"id": "f2", "type": "textarea", "label": "How quickly that reaction passed"}, {"id": "f3", "type": "textarea", "label": "What I noticed about wanting to control it"}]'::jsonb, array['OCD', 'uncertainty', 'group']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('ritual-urge-surf-card', 'Ritual Urge Surf Card', 'dbt'::resource_kind, 'Applies urge-surfing to a compulsion urge, riding out the wave instead of completing the ritual.', 'Give the client a skill for the moment between the urge and the ritual, not just afterward.', array['Adults', 'Teens']::text[], 'In the moment', 'When the urge to complete a ritual shows up, have the client rate its intensity, then use a paced breathing or grounding skill while tracking the intensity every minute or two instead of acting on the urge right away. Most urges crest and start to fade well before the client expects. Log how long the wave actually lasted to build evidence for next time.', '[{"id": "f0", "type": "textarea", "label": "The urge and its trigger"}, {"id": "f1", "type": "textarea", "label": "Starting intensity, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Intensity checked every few minutes"}, {"id": "f3", "type": "textarea", "label": "How long until it faded"}, {"id": "f4", "type": "textarea", "label": "What I did instead of the ritual"}]'::jsonb, array['OCD', 'urges', 'core DBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('panic-helper-kit-craft', 'Panic Helper Kit Craft', 'kids'::resource_kind, 'A child and parent build a small kit of comfort items and reminders for a scary panic moment.', 'Give a child a concrete, ready kit instead of trying to remember what helps mid-panic.', array['Children']::text[], '20 minutes', 'The parent and child fill a small pouch together with a comfort item, a reminder card of a calming phrase, and a picture of a safe person, deciding together what goes in. Practice opening the kit and using each item during a calm moment so it is familiar rather than confusing later. Keep the kit somewhere the child can reach without a grown-up.', '[{"id": "f0", "type": "textarea", "label": "What I put in my kit"}, {"id": "f1", "type": "textarea", "label": "My calming phrase"}, {"id": "f2", "type": "textarea", "label": "Who is in my safe person picture"}, {"id": "f3", "type": "textarea", "label": "A time I want to practice using my kit"}]'::jsonb, array['panic attacks', 'children', 'play']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('panic-fact-relay-game', 'Panic Fact Relay Game', 'game'::resource_kind, 'A relay-style group game answering true or false questions about what panic sensations actually mean.', 'Correct common catastrophic misreadings of panic sensations through quick, repeated practice.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Split into teams and relay through a stack of true-or-false cards about panic sensations, such as whether a racing heart during panic is dangerous on its own. Getting a fact wrong is not a penalty, just a chance to discuss it as a group before moving on. The repetition across many rounds does more to correct catastrophic misreadings than a single explanation.', '[{"id": "f0", "type": "textarea", "label": "A fact card that surprised me"}, {"id": "f1", "type": "textarea", "label": "A misreading I realized I hold"}, {"id": "f2", "type": "textarea", "label": "The corrected version"}, {"id": "f3", "type": "textarea", "label": "How this changes what I do during a panic sensation"}]'::jsonb, array['panic attacks', 'group', 'thinking traps']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('panic-willingness-ladder', 'Panic Willingness Ladder', 'act'::resource_kind, 'Builds a graded ladder of situations, ranked by how much willingness to feel panic sensations each one takes.', 'Practice willingness in graded steps instead of an all-or-nothing leap.', array['Adults', 'Teens']::text[], '20 minutes to build, then ongoing', 'List situations that bring on panic sensations, from mildly uncomfortable to most avoided, and rank them by how much willingness each one would take right now. Start practicing willingness at the bottom of the ladder rather than the top, since a small, winnable step builds more confidence than a large one that fails. Move up the ladder only as willingness genuinely grows.', '[{"id": "f0", "type": "textarea", "label": "A situation near the bottom of my ladder"}, {"id": "f1", "type": "textarea", "label": "A situation near the top"}, {"id": "f2", "type": "textarea", "label": "My willingness rating for the bottom one now, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What practicing at that step looked like"}, {"id": "f4", "type": "textarea", "label": "When I feel ready to move up"}]'::jsonb, array['panic attacks', 'willingness', 'core ACT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('panic-descent-tracker', 'Panic Descent Tracker', 'dbt'::resource_kind, 'Tracks how long a panic episode actually takes to fade once it peaks, building a record over time.', 'Give the client their own evidence for how long panic actually lasts, not how long it feels like it lasts.', array['Adults', 'Teens']::text[], 'Ongoing, a few minutes per episode', 'After a panic episode, have the client note the peak intensity and roughly how long it took to noticeably fade, without needing to catch every detail in the moment. Panic almost always peaks and starts descending within minutes, but it rarely feels that way while it is happening. A growing log of real descent times becomes more convincing than being told the timeline in the abstract.', '[{"id": "f0", "type": "textarea", "label": "When the episode started"}, {"id": "f1", "type": "textarea", "label": "Peak intensity, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Roughly how long until it noticeably faded"}, {"id": "f3", "type": "textarea", "label": "What I did during it"}, {"id": "f4", "type": "textarea", "label": "What I notice across several logged episodes"}]'::jsonb, array['panic attacks', 'core DBT', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('panic-trigger-environment-map', 'Panic Trigger Environment Map', 'worksheet'::resource_kind, 'Maps the places, times and situations where panic episodes have actually occurred.', 'Separate real situational patterns from the sense that panic could strike absolutely anywhere.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client list recent panic episodes along with the place, time of day and what was happening just before each one. Panic often feels completely random, but a map across several episodes frequently reveals a pattern the client had not noticed. Use the map to decide where extra preparation or support might help most, without turning it into a reason to avoid those places.', '[{"id": "f0", "type": "textarea", "label": "A recent panic episode: place and time"}, {"id": "f1", "type": "textarea", "label": "What was happening just before"}, {"id": "f2", "type": "textarea", "label": "Another episode: place and time"}, {"id": "f3", "type": "textarea", "label": "What was happening just before that one"}, {"id": "f4", "type": "textarea", "label": "A pattern I am starting to notice"}]'::jsonb, array['panic attacks', 'self-monitoring', 'formulation']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('parent-assumed-intent-check', 'Parent Assumed Intent Check', 'cbt'::resource_kind, 'Tests a parent''s assumption about why their child misbehaved against other explanations that fit just as well.', 'Slow down a parent''s story about a child''s motive before it drives a harsher response than needed.', array['Adults']::text[], '15 minutes', 'Ask the parent what they believe their child''s misbehavior meant, defiance, disrespect, manipulation, then list other explanations that fit the same facts, such as tiredness, a skill the child has not built yet, or a need not being met. Parents often respond to the story about the behavior more than the behavior itself. Practice picking the most generous explanation that still fits the facts before responding next time.', '[{"id": "f0", "type": "textarea", "label": "What my child did"}, {"id": "f1", "type": "textarea", "label": "What I believed it meant"}, {"id": "f2", "type": "textarea", "label": "Other explanations that fit the same facts"}, {"id": "f3", "type": "textarea", "label": "How confident I am in my original story, 0 to 100"}, {"id": "f4", "type": "textarea", "label": "The most generous explanation that still fits"}, {"id": "f5", "type": "textarea", "label": "How I want to respond next time, given that"}]'::jsonb, array['parenting', 'thinking traps', 'core CBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('values-based-discipline-pause', 'Values-Based Discipline Pause', 'act'::resource_kind, 'Chooses a discipline response that fits the parent''s values, not just the urge of the moment.', 'Give a parent a values check to run through before reacting in a heated discipline moment.', array['Adults']::text[], '15 minutes', 'Ask what kind of parent the client wants to be in a hard moment, then compare that to how a recent discipline moment actually went. The gap is not a verdict on the parent, just information about where the urge of the moment took over. Practice naming the value out loud, even silently, in the pause before responding next time.', '[{"id": "f0", "type": "textarea", "label": "The kind of parent I want to be in a hard moment"}, {"id": "f1", "type": "textarea", "label": "A recent discipline moment"}, {"id": "f2", "type": "textarea", "label": "How it actually went"}, {"id": "f3", "type": "textarea", "label": "What got in the way of the value I wanted"}, {"id": "f4", "type": "textarea", "label": "A phrase to help me pause before reacting next time"}]'::jsonb, array['parenting', 'values', 'core ACT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('parent-wise-mind-pause', 'Parent Wise Mind Pause', 'dbt'::resource_kind, 'Gives a parent a short pause practice to find wise mind before responding to a child''s behavior.', 'Interrupt an emotional-mind reaction with a brief, practiced pause before responding to a child.', array['Adults']::text[], '10 minutes to learn, then in the moment', 'Teach the parent a short pause, a breath and a single grounding question, what does this moment actually need, to use in the gap between a child''s behavior and the parent''s response. This is not about suppressing the emotion, only about not acting straight from it. Practice the pause in a calm role-play before expecting it to hold up during an actual flashpoint.', '[{"id": "f0", "type": "textarea", "label": "A recent moment I reacted before I meant to"}, {"id": "f1", "type": "textarea", "label": "What emotional mind wanted to do"}, {"id": "f2", "type": "textarea", "label": "What the pause question brought up instead"}, {"id": "f3", "type": "textarea", "label": "A moment coming up where I want to practice this"}]'::jsonb, array['parenting', 'core DBT', 'regulation']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('discipline-alignment-conversation', 'Discipline Alignment Conversation', 'couples'::resource_kind, 'Gets both parents on the same page about consequences before the next discipline moment, not during it.', 'Prevent a child from playing mismatched parents against each other by aligning ahead of time.', array['Couples']::text[], '25 minutes', 'Ask each parent to describe how they typically respond to a common misbehavior, then find where the approaches match and where they genuinely differ. Disagreeing in front of the child usually costs more than picking an imperfect but shared approach. Agree on one consistent response for one common situation and revisit after trying it for a week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I typically respond to this"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I typically respond to this"}, {"id": "f2", "type": "textarea", "label": "Where we already agree"}, {"id": "f3", "type": "textarea", "label": "Where we differ"}, {"id": "f4", "type": "textarea", "label": "The shared approach we agreed to try"}]'::jsonb, array['parenting', 'communication', 'couples']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('would-you-say-that-to-a-friend-parent-game', 'Would You Say That to a Friend? Parent Game', 'game'::resource_kind, 'A parent group rewrites a harsh line they have said to their child into one they would say to a friend''s kid.', 'Use a quick reframing game to build a gentler, still-clear discipline voice.', array['Groups', 'Adults']::text[], '20 minutes', 'Each parent shares a line they have said in frustration, then the group rewrites it as something they would say to a friend''s child in the same situation, keeping the same limit but changing the tone. Notice out loud how the rewritten version still sets the limit without the harshness. Take the rewritten lines home to try during the next real moment.', '[{"id": "f0", "type": "textarea", "label": "The original line"}, {"id": "f1", "type": "textarea", "label": "The rewritten version"}, {"id": "f2", "type": "textarea", "label": "What changed between the two"}, {"id": "f3", "type": "textarea", "label": "A moment this week I want to try the rewrite"}]'::jsonb, array['parenting', 'group', 'communication']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('big-sibling-helper-craft', 'Big Sibling Helper Craft', 'kids'::resource_kind, 'An older sibling decorates a helper badge and picks small ways to help with a new baby.', 'Give an older sibling a positive role during a family transition instead of feeling displaced.', array['Children']::text[], '20 minutes', 'The parent and older child decorate a simple badge together, then pick a short list of small, real jobs the child can do to help with the new baby, such as choosing an outfit or singing a song during a diaper change. Praise the helping specifically rather than just being good. Check in regularly about how the child is feeling about all the change, not just the helping.', '[{"id": "f0", "type": "textarea", "label": "My helper jobs"}, {"id": "f1", "type": "textarea", "label": "My favorite one so far"}, {"id": "f2", "type": "textarea", "label": "How I feel about all the changes at home"}, {"id": "f3", "type": "textarea", "label": "Something I miss having more of"}]'::jsonb, array['perinatal and postpartum', 'children', 'family']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('new-parent-worry-sorting-sheet', 'New Parent Worry Sorting Sheet', 'cbt'::resource_kind, 'Sorts a new parent''s worries into ones worth a plan and ones that just need to be noticed and set down.', 'Reduce the load of constant worry by separating what needs action from what does not.', array['Adults']::text[], '15 minutes', 'Have the new parent list current worries, then sort each into one that has a concrete next step and one that is really just uncertainty running on a loop. The first group gets a short plan; the second group gets practice noticing and setting down, since planning has nothing left to grab onto there. Revisit the sorted list weekly as new worries replace old ones.', '[{"id": "f0", "type": "textarea", "label": "A current worry"}, {"id": "f1", "type": "textarea", "label": "Does it have a concrete next step"}, {"id": "f2", "type": "textarea", "label": "If yes, the step"}, {"id": "f3", "type": "textarea", "label": "If no, what noticing and setting it down looks like"}, {"id": "f4", "type": "textarea", "label": "How the sorted list feels compared to the raw list"}]'::jsonb, array['perinatal and postpartum', 'thinking traps', 'core CBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('postpartum-self-soothe-menu', 'Postpartum Self-Soothe Menu', 'dbt'::resource_kind, 'Builds a five-senses self-soothe menu realistic for the short, interrupted windows of early parenthood.', 'Give a new parent soothing options that actually fit a newborn''s schedule, not a full self-care routine.', array['Adults']::text[], '15 minutes', 'Build the self-soothe menu around what is actually available in a two-minute window with a baby nearby: a scent kept by the changing table, a song, a warm mug within reach. Skip anything that requires leaving the room or a long stretch of time, since that version of self-care usually goes unused right now. Revisit the menu as the baby''s schedule changes.', '[{"id": "f0", "type": "textarea", "label": "A soothing option that fits a two-minute window"}, {"id": "f1", "type": "textarea", "label": "Another one"}, {"id": "f2", "type": "textarea", "label": "Where I will keep each one within reach"}, {"id": "f3", "type": "textarea", "label": "One I actually used this week"}]'::jsonb, array['perinatal and postpartum', 'distress tolerance', 'core DBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('birth-recovery-expectations-reset', 'Birth Recovery Expectations Reset', 'worksheet'::resource_kind, 'Compares what a client expected postpartum recovery to feel like against how it has actually gone.', 'Close the gap between an unrealistic recovery expectation and what is actually normal and survivable.', array['Adults']::text[], '15 minutes', 'Have the client write down what they expected recovery to look like by this point and what it has actually looked like, in plain terms. The gap is often the source of a lot of quiet shame, and naming it plainly tends to loosen that. Ask what a more realistic expectation for the next stretch would sound like.', '[{"id": "f0", "type": "textarea", "label": "What I expected recovery to look like by now"}, {"id": "f1", "type": "textarea", "label": "What it has actually looked like"}, {"id": "f2", "type": "textarea", "label": "What the gap has felt like to carry"}, {"id": "f3", "type": "textarea", "label": "A more realistic expectation for the next stretch"}]'::jsonb, array['perinatal and postpartum', 'self-compassion', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('new-parent-trivia-swap', 'New Parent Trivia Swap', 'game'::resource_kind, 'A group game where new parents trade one true surprise and one common myth about early parenthood.', 'Normalize the surprises of new parenthood through shared, low-stakes group disclosure.', array['Groups', 'Adults']::text[], '20 minutes', 'Going around the group, each parent shares one thing about early parenthood that genuinely surprised them and one myth they had believed beforehand, and the group guesses which is which before finding out. The game format lowers the pressure of admitting something feels harder than expected. Debrief on what it was like to hear how common the surprises are.', '[{"id": "f0", "type": "textarea", "label": "My surprise"}, {"id": "f1", "type": "textarea", "label": "My myth"}, {"id": "f2", "type": "textarea", "label": "A surprise from someone else that stuck with me"}, {"id": "f3", "type": "textarea", "label": "What it was like to hear how common these are"}]'::jsonb, array['perinatal and postpartum', 'group', 'support']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('self-worth-beyond-achievement-practice', 'Self-Worth Beyond Achievement Practice', 'act'::resource_kind, 'Separates a client''s sense of worth from their most recent achievement or failure.', 'Loosen the tie between self-worth and performance so a bad day does not define the client.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to notice how much their sense of worth moved after a recent win and after a recent setback, then ask what stayed the same underneath both. Worth tied entirely to achievement means it is never stable for long. Practice naming something true about the client that does not depend on the outcome of anything.', '[{"id": "f0", "type": "textarea", "label": "A recent win, and how my worth moved"}, {"id": "f1", "type": "textarea", "label": "A recent setback, and how my worth moved"}, {"id": "f2", "type": "textarea", "label": "What stayed the same underneath both"}, {"id": "f3", "type": "textarea", "label": "Something true about me that does not depend on outcomes"}]'::jsonb, array['self-esteem', 'values', 'core ACT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-self-talk-practice', 'Nonjudgmental Self-Talk Practice', 'dbt'::resource_kind, 'Catches a judging word aimed at the self and rewrites it as a plain, descriptive statement.', 'Practice describing behavior instead of judging the self for it.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client notice a recent moment of harsh self-talk, identify the judging word, such as stupid, lazy, or failure, and rewrite the statement using only what actually happened, without the label. This is a specific application of a nonjudgmental stance turned toward the self rather than outward. Practice catching the judging word earlier each time it shows up.', '[{"id": "f0", "type": "textarea", "label": "A recent moment of harsh self-talk"}, {"id": "f1", "type": "textarea", "label": "The judging word"}, {"id": "f2", "type": "textarea", "label": "What actually happened, described plainly"}, {"id": "f3", "type": "textarea", "label": "How the plain version feels compared to the judgment"}]'::jsonb, array['self-esteem', 'core DBT', 'self-talk']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('reflected-worth-check-in', 'Reflected Worth Check-In', 'couples'::resource_kind, 'Checks in on how each partner''s recent comments have landed on the other''s sense of worth.', 'Catch an unintentional pattern of comments that chip at a partner''s self-esteem before it settles in.', array['Couples']::text[], '20 minutes', 'Ask each partner to name a recent comment, even a joking one, that landed harder than intended, and a recent comment that genuinely helped their sense of worth. Most partners are unaware of the specific comments that stick. Agree on one thing each partner will say more of and one they will watch for going forward.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a comment that landed harder than intended"}, {"id": "f1", "type": "textarea", "label": "Partner A: a comment that genuinely helped"}, {"id": "f2", "type": "textarea", "label": "Partner B: a comment that landed harder than intended"}, {"id": "f3", "type": "textarea", "label": "Partner B: a comment that genuinely helped"}, {"id": "f4", "type": "textarea", "label": "What each of us wants to watch for going forward"}]'::jsonb, array['self-esteem', 'communication', 'couples']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('strength-swap-circle', 'Strength Swap Circle', 'game'::resource_kind, 'Each group member shares a strength someone else named in them that they had not noticed themselves.', 'Build a fuller, more accurate self-view using strengths the group actually observed.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Before the game, collect one strength each member has shown in group from the facilitator''s own notes or quick peer input, then reveal them one at a time without saying who it is about until the member guesses. Being handed a strength observed by someone else often lands differently than naming one for yourself. Close by asking each member to say the strength out loud in their own words.', '[{"id": "f0", "type": "textarea", "label": "The strength that was named for me"}, {"id": "f1", "type": "textarea", "label": "Whether I had noticed it in myself before"}, {"id": "f2", "type": "textarea", "label": "How it felt to hear it from the group"}, {"id": "f3", "type": "textarea", "label": "Saying it in my own words"}]'::jsonb, array['self-esteem', 'strengths', 'group']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('self-esteem-weather-log', 'Self-Esteem Weather Log', 'worksheet'::resource_kind, 'Tracks how much a client''s sense of self-worth swings from day to day and what tends to drive the swings.', 'Show the client that self-esteem naturally fluctuates rather than being a fixed, failing trait.', array['Adults', 'Teens']::text[], 'One week', 'Each day, have the client rate their overall sense of self-worth and note anything that seemed to move it up or down. Most clients discover their self-esteem moves with events and comparisons rather than staying low consistently, which is itself useful information. Use the week''s pattern to spot the specific triggers worth working on directly.', '[{"id": "f0", "type": "textarea", "label": "Today''s self-worth rating, 0 to 10"}, {"id": "f1", "type": "textarea", "label": "What moved it up, if anything"}, {"id": "f2", "type": "textarea", "label": "What moved it down, if anything"}, {"id": "f3", "type": "textarea", "label": "A pattern I notice across the week"}]'::jsonb, array['self-esteem', 'self-monitoring', 'thinking traps']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('social-event-support-plan-for-partners', 'Social Event Support Plan for Partners', 'couples'::resource_kind, 'Plans in advance how a partner can help before, during and after a social event that brings on anxiety.', 'Give both partners a concrete plan instead of improvising support in the middle of an event.', array['Couples']::text[], '20 minutes', 'Before an upcoming event, ask the anxious partner what kind of support actually helps at each stage, before leaving, once there, and on the way home, and ask the other partner what they can realistically offer at each point. Agree on a subtle signal for when the anxious partner needs a break. Debrief afterward on what worked so the plan improves for next time.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps before we leave"}, {"id": "f1", "type": "textarea", "label": "Partner A: what helps once we are there"}, {"id": "f2", "type": "textarea", "label": "Partner A: what helps on the way home"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I can realistically offer at each point"}, {"id": "f4", "type": "textarea", "label": "Our signal for needing a break"}, {"id": "f5", "type": "textarea", "label": "What we want to adjust next time"}]'::jsonb, array['social anxiety', 'support', 'couples']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('social-anxiety-cost-of-avoidance-sheet', 'Social Anxiety Cost of Avoidance Sheet', 'worksheet'::resource_kind, 'Tallies what avoiding a social situation actually cost against the short-term relief it gave.', 'Make the long-term cost of social avoidance as visible as the short-term relief that drives it.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client list a few recent situations they avoided because of social anxiety, note the relief avoidance gave right away, and separately note what it cost over the following days or weeks: a missed connection, an opportunity, a growing sense of isolation. The relief column usually wins in the moment while the cost column wins over time. Use the comparison to choose one situation worth approaching differently next time.', '[{"id": "f0", "type": "textarea", "label": "A situation I avoided"}, {"id": "f1", "type": "textarea", "label": "The relief avoidance gave right away"}, {"id": "f2", "type": "textarea", "label": "What it cost over the following days or weeks"}, {"id": "f3", "type": "textarea", "label": "A situation I want to approach differently next time"}]'::jsonb, array['social anxiety', 'avoidance', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('small-talk-bingo', 'Small Talk Bingo', 'game'::resource_kind, 'A bingo card of small talk topics group members practice bringing up with each other during the session.', 'Turn practicing small talk into a low-pressure, structured game instead of an open-ended ordeal.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Give each member a bingo card of common small talk topics and have them mingle, marking a square each time they successfully bring one up with another member. Because the topic is assigned by the card, no one has to come up with what to say on the spot, which is usually the hardest part. Debrief on which squares felt easiest and which took the most nerve.', '[{"id": "f0", "type": "textarea", "label": "A square that felt easy"}, {"id": "f1", "type": "textarea", "label": "A square that took nerve"}, {"id": "f2", "type": "textarea", "label": "What helped me approach someone"}, {"id": "f3", "type": "textarea", "label": "How I feel now compared to before we started"}]'::jsonb, array['social anxiety', 'group', 'exposure']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('post-social-self-validation-card', 'Post-Social Self-Validation Card', 'dbt'::resource_kind, 'Has the client validate their own effort after a social event instead of only reviewing what went wrong.', 'Balance the post-event replay with credit for the effort it took to show up at all.', array['Adults', 'Teens']::text[], '10 minutes', 'Right after a social event, before the rumination has a chance to take over, have the client write down what it took to show up and one thing that went fine, alongside anything that felt awkward. This is not about ignoring what went wrong, only about not letting it stand alone. Use the card as a fixed first step before any longer post-event review.', '[{"id": "f0", "type": "textarea", "label": "The event"}, {"id": "f1", "type": "textarea", "label": "What it took to show up"}, {"id": "f2", "type": "textarea", "label": "One thing that went fine"}, {"id": "f3", "type": "textarea", "label": "Anything that felt awkward"}, {"id": "f4", "type": "textarea", "label": "What I want to remember about tonight"}]'::jsonb, array['social anxiety', 'core DBT', 'self-compassion']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('social-anxiety-attention-trap-log', 'Social Anxiety Attention Trap Log', 'cbt'::resource_kind, 'Logs the moments during a social situation when attention turned inward instead of outward.', 'Show the client how often self-focused attention, not the situation itself, drives the discomfort.', array['Adults', 'Teens']::text[], 'One week', 'After a social situation, have the client note moments they noticed their attention turn toward monitoring themselves, how they looked, sounded, or were being judged, versus moments they were tuned into the actual conversation. Self-focused attention tends to amplify anxiety and cost the client information about how the interaction is really going. Use the log to plan where to practice redirecting attention outward.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "A moment attention turned inward"}, {"id": "f2", "type": "textarea", "label": "What it was focused on"}, {"id": "f3", "type": "textarea", "label": "A moment attention was on the actual conversation"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the difference"}]'::jsonb, array['social anxiety', 'self-monitoring', 'core CBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('grief-wave-distress-tolerance-card', 'Grief Wave Distress Tolerance Card', 'dbt'::resource_kind, 'A card of distress tolerance skills sized for the sudden waves of grief that can hit without warning.', 'Give the client fast options for the moment a wave of grief arrives, not just the planned ones.', array['Adults', 'Teens']::text[], '15 minutes to build, then in the moment', 'Grief waves often arrive without warning, in a store, a meeting, a quiet moment, so build a short card of skills that work fast and do not require leaving wherever the client is. Distinguish these from longer coping strategies that need privacy or time, since a wave rarely gives that much notice. Test the card during a smaller wave first.', '[{"id": "f0", "type": "textarea", "label": "A skill that works fast, wherever I am"}, {"id": "f1", "type": "textarea", "label": "Another one"}, {"id": "f2", "type": "textarea", "label": "Where I will keep this card"}, {"id": "f3", "type": "textarea", "label": "A recent wave, and what I used"}]'::jsonb, array['grief and loss', 'distress tolerance', 'core DBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('carrying-grief-and-living-forward-practice', 'Carrying Grief and Living Forward Practice', 'act'::resource_kind, 'Practices holding grief and a moving-forward life at the same time, rather than treating them as opposites.', 'Loosen the idea that moving forward means leaving the person or loss behind.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client what moving forward seems to require giving up, then explore whether grief and a forward-moving life can actually sit side by side rather than trading off. Most clients carry an unspoken rule that healing means forgetting, which this gently questions. Practice naming one value-based step forward the client can take while still carrying the grief, not after it is gone.', '[{"id": "f0", "type": "textarea", "label": "What moving forward seems to require giving up"}, {"id": "f1", "type": "textarea", "label": "Whether that rule feels true when I look at it closely"}, {"id": "f2", "type": "textarea", "label": "What I want to keep carrying regardless"}, {"id": "f3", "type": "textarea", "label": "One step forward I can take while still carrying this"}]'::jsonb, array['grief and loss', 'values', 'core ACT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('grief-support-circle-map', 'Grief Support Circle Map', 'worksheet'::resource_kind, 'Maps who in a client''s life can hold which part of their grief, since no one person can hold all of it.', 'Spread the weight of grief across a wider circle instead of resting it all on one relationship.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client list people in their life and what each one is actually good for around this loss: practical help, sitting in silence, talking about the person who died, distraction. Expecting one person to be everything often strains that relationship and leaves other kinds of support unused. Use the map to reach out more deliberately for what is actually needed.', '[{"id": "f0", "type": "textarea", "label": "A person in my circle"}, {"id": "f1", "type": "textarea", "label": "What they are good for around this loss"}, {"id": "f2", "type": "textarea", "label": "Another person"}, {"id": "f3", "type": "textarea", "label": "What they are good for"}, {"id": "f4", "type": "textarea", "label": "A kind of support I am not getting from anyone yet"}]'::jsonb, array['grief and loss', 'support', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('remembering-ritual-craft', 'Remembering Ritual Craft', 'kids'::resource_kind, 'A child and parent create a small, repeatable ritual for remembering someone who died.', 'Give a child a concrete, repeatable way to stay connected to a memory instead of one that only happens once.', array['Children']::text[], '20 minutes', 'The parent and child choose something simple that can be repeated, like watering a plant chosen in the person''s memory or looking at a photo together on a set day, and agree on when they will do it. A repeatable ritual gives grief a regular, predictable place to go instead of showing up unexpectedly. Let the child decide how long they want to keep the ritual going.', '[{"id": "f0", "type": "textarea", "label": "Our ritual"}, {"id": "f1", "type": "textarea", "label": "When we do it"}, {"id": "f2", "type": "textarea", "label": "What I think about during it"}, {"id": "f3", "type": "textarea", "label": "How I want the ritual to change over time"}]'::jsonb, array['grief and loss', 'children', 'family']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('grief-thought-sorting-sheet', 'Grief Thought Sorting Sheet', 'cbt'::resource_kind, 'Sorts a client''s grief-related thoughts into ones worth sitting with and ones worth gently questioning.', 'Help the client tell painful-but-true grief thoughts apart from distorted ones adding extra suffering.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client list thoughts that have come up since the loss, then sort each into one that is simply a true, painful part of grieving and one that adds extra suffering through distortion, such as an all-or-nothing judgment about how they are grieving. The first group gets space and time; the second gets gently questioned. Revisit the sort as new thoughts come up.', '[{"id": "f0", "type": "textarea", "label": "A grief-related thought"}, {"id": "f1", "type": "textarea", "label": "True and painful, or distorted and adding suffering"}, {"id": "f2", "type": "textarea", "label": "If distorted, a gentler version that still fits the facts"}, {"id": "f3", "type": "textarea", "label": "What this thought needs from me right now"}]'::jsonb, array['grief and loss', 'thinking traps', 'core CBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('relationship-expectations-inventory', 'Relationship Expectations Inventory', 'worksheet'::resource_kind, 'Lists what a client expects from a relationship and where those expectations were formed.', 'Trace an unspoken expectation back to its source before deciding whether it still fits.', array['Adults', 'Couples']::text[], '20 minutes', 'Have the client list expectations they hold for a close relationship, then ask where each one came from: a family pattern, a past relationship, a cultural message. An expectation that made sense in its original context does not always fit the current relationship, and naming the source often loosens its grip. Sort the list into expectations worth keeping and ones worth revisiting.', '[{"id": "f0", "type": "textarea", "label": "An expectation I hold for this relationship"}, {"id": "f1", "type": "textarea", "label": "Where it came from"}, {"id": "f2", "type": "textarea", "label": "Whether it fits this relationship as it actually is"}, {"id": "f3", "type": "textarea", "label": "Worth keeping or worth revisiting"}]'::jsonb, array['relationship issues', 'self-monitoring', 'family']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('assumed-intent-log', 'Assumed Intent Log', 'cbt'::resource_kind, 'Logs an assumed intent behind someone''s action in a relationship and checks it against what they actually meant.', 'Slow down a confident story about someone''s intent before it drives a reaction.', array['Adults', 'Couples']::text[], '15 minutes', 'Have the client write down what they assumed someone meant by a recent action, then, when possible, check that assumption against what the person actually says they meant. The gap between assumed and actual intent is often wide enough to be worth noticing on its own, even without checking. Use the log to build the habit of holding an assumption loosely until it is confirmed.', '[{"id": "f0", "type": "textarea", "label": "The action"}, {"id": "f1", "type": "textarea", "label": "What I assumed it meant"}, {"id": "f2", "type": "textarea", "label": "How confident I was, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What they actually meant, if I checked"}, {"id": "f4", "type": "textarea", "label": "What I notice about the gap"}]'::jsonb, array['relationship issues', 'core CBT', 'thinking traps']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('friendship-repair-practice-cards', 'Friendship Repair Practice Cards', 'kids'::resource_kind, 'A child practices short repair phrases for after a fight with a friend, using illustrated cue cards.', 'Give a child a rehearsed script for repairing a friendship instead of avoiding the friend afterward.', array['Children']::text[], '20 minutes', 'The parent and child make a small set of illustrated cards with simple repair phrases, such as asking to talk or saying what happened without blaming, and practice using them in a pretend fight scenario. Rehearsing the words in a low-stakes moment makes them easier to reach for during a real one. Check in after the child tries a real repair to see how it went.', '[{"id": "f0", "type": "textarea", "label": "The cards I made"}, {"id": "f1", "type": "textarea", "label": "The one I practiced most"}, {"id": "f2", "type": "textarea", "label": "A real fight I want to try repairing"}, {"id": "f3", "type": "textarea", "label": "How the repair went"}]'::jsonb, array['relationship issues', 'children', 'communication']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('friendship-values-sort-game', 'Friendship Values Sort Game', 'game'::resource_kind, 'A group sorts cards describing friendship qualities into what matters most to them, then compares.', 'Help group members clarify what they actually value in a relationship, out loud and together.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Give each member a set of cards naming relationship qualities, such as honesty, humor, reliability, and have them sort a limited number into their top choices before comparing with the group. Differences in ranking are a useful discussion point, not a disagreement to resolve. Ask what it would look like to bring more of a top-ranked quality into a current relationship.', '[{"id": "f0", "type": "textarea", "label": "My top three qualities"}, {"id": "f1", "type": "textarea", "label": "One I was surprised to rank low"}, {"id": "f2", "type": "textarea", "label": "A quality someone else ranked high that I had not considered"}, {"id": "f3", "type": "textarea", "label": "How I could bring more of my top quality into a relationship"}]'::jsonb, array['relationship issues', 'values', 'group']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('interpersonal-check-the-facts-sheet', 'Interpersonal Check the Facts Sheet', 'dbt'::resource_kind, 'Checks a client''s interpretation of a relationship conflict against the facts before deciding how to respond.', 'Separate the interpretation of a conflict from the facts of what actually happened.', array['Adults', 'Couples']::text[], '15 minutes', 'Have the client describe a recent conflict in plain facts first, then separately write the interpretation or story they added on top. Emotion often follows the interpretation more than the facts themselves, so checking whether the interpretation actually fits is worth doing before responding. Ask what a response based only on the facts would look like.', '[{"id": "f0", "type": "textarea", "label": "The facts of a recent conflict"}, {"id": "f1", "type": "textarea", "label": "My interpretation on top of the facts"}, {"id": "f2", "type": "textarea", "label": "How well the interpretation actually fits"}, {"id": "f3", "type": "textarea", "label": "A response based only on the facts"}]'::jsonb, array['relationship issues', 'core DBT', 'thinking traps']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('present-day-safety-routine-builder', 'Present-Day Safety Routine Builder', 'worksheet'::resource_kind, 'Builds a short daily routine of small actions that reinforce a survivor''s present-day safety and choice.', 'Give the client repeated, everyday evidence of safety and choice in the present.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to choose a few small daily actions that reinforce that they are safe and in control now, such as locking a door themselves, choosing what to eat, deciding when to end a conversation. Complete this together in session rather than as homework the first time. The routine is not about the past; it is about building present-day evidence, repeated until it settles in.', '[{"id": "f0", "type": "textarea", "label": "A small action that reinforces my present safety"}, {"id": "f1", "type": "textarea", "label": "Another one"}, {"id": "f2", "type": "textarea", "label": "How choosing it makes me feel"}, {"id": "f3", "type": "textarea", "label": "When I will build this into my day"}, {"id": "f4", "type": "textarea", "label": "Who I can tell if I need support with this"}]'::jsonb, array['sexual abuse', 'safety', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('self-blame-statement-rewrite', 'Self-Blame Statement Rewrite', 'cbt'::resource_kind, 'Rewrites a self-blaming statement a survivor holds about what happened into a fairer, plainer one.', 'Loosen self-blame by testing it against what a client would actually say to someone else in their place.', array['Adults', 'Teens']::text[], 'Full session', 'Complete this in session, not as homework. Ask the client to state a self-blaming belief about what happened, then ask what they would say to a friend who told them the exact same story. The gap between the two is usually large and worth sitting with. Write a fairer statement together without asking the client to describe what happened in detail; the belief, not the account, is the focus.', '[{"id": "f0", "type": "textarea", "label": "A self-blaming belief I hold"}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend with the same story"}, {"id": "f2", "type": "textarea", "label": "The gap between those two responses"}, {"id": "f3", "type": "textarea", "label": "A fairer statement, in my own words"}, {"id": "f4", "type": "textarea", "label": "How believable the fairer statement feels right now"}]'::jsonb, array['sexual abuse', 'shame', 'core CBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('compassion-for-the-part-that-survived-practice', 'Compassion for the Part That Survived Practice', 'act'::resource_kind, 'Directs compassion toward the part of the client that found a way to survive, rather than judging how.', 'Replace judgment about coping strategies with acknowledgment that they served a real purpose.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client what part of them found a way to get through, and what that part needed at the time, without asking for the details of what happened. Many survivors judge the ways they coped rather than crediting that some part of them found a way forward at all. Practice speaking to that part with the same compassion the client would offer someone else who had survived something hard.', '[{"id": "f0", "type": "textarea", "label": "What I judge about how I got through"}, {"id": "f1", "type": "textarea", "label": "What that part of me actually needed at the time"}, {"id": "f2", "type": "textarea", "label": "What I would say to someone else who coped this way"}, {"id": "f3", "type": "textarea", "label": "What I want to say to that part of myself now"}]'::jsonb, array['sexual abuse', 'self-compassion', 'core ACT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('body-safety-grounding-sequence', 'Body Safety Grounding Sequence', 'dbt'::resource_kind, 'Pairs a short physical grounding sequence with a spoken safety phrase, practiced until it feels automatic.', 'Build a fast, physical route back to a felt sense of safety in the body.', array['Adults', 'Teens']::text[], '15 minutes to build, then in the moment', 'Build a short sequence together, feet flat on the floor, hands pressed together, a slow breath, paired with a spoken phrase such as I am here now, I am safe enough. Rehearse it in session while calm and again at a mild activation level so it is familiar before it is needed under real pressure. Include 988, call or text, as a backup on the card.', '[{"id": "f0", "type": "textarea", "label": "My grounding sequence, step by step"}, {"id": "f1", "type": "textarea", "label": "My spoken phrase"}, {"id": "f2", "type": "textarea", "label": "A moment I rehearsed it"}, {"id": "f3", "type": "textarea", "label": "How it felt"}, {"id": "f4", "type": "textarea", "label": "988, call or text, if it is not enough"}]'::jsonb, array['sexual abuse', 'grounding', 'core DBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('consent-check-in-ritual-for-survivors', 'Consent Check-In Ritual for Survivors', 'couples'::resource_kind, 'Builds a regular, low-pressure way for a survivor and partner to check in about physical closeness.', 'Give both partners an ongoing, spoken way to check in on consent rather than assuming it.', array['Couples']::text[], '20 minutes', 'Have the couple agree on a simple, spoken check-in they will use before physical closeness, along with a clear, easy way for either partner to pause or stop without it becoming a bigger conversation in the moment. This works only when both partners agree to honor a pause immediately and without argument. Revisit the ritual regularly as comfort levels shift.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need in this check-in"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need in this check-in"}, {"id": "f2", "type": "textarea", "label": "Our words for checking in"}, {"id": "f3", "type": "textarea", "label": "Our words or signal for pausing"}, {"id": "f4", "type": "textarea", "label": "What we agreed happens after a pause"}]'::jsonb, array['sexual abuse', 'consent', 'couples']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('coping-together-menu', 'Coping Together Menu', 'couples'::resource_kind, 'Builds a shared list of coping activities partners can do side by side during a hard stretch.', 'Give a couple options for supporting each other through stress without one partner having to fix it.', array['Couples']::text[], '15 minutes', 'Have both partners list coping activities that work better done together than alone, such as a walk, cooking, or sitting in silence in the same room, and agree on a simple way to offer one when either partner is struggling. This gives support a concrete shape instead of a vague offer to help. Try one option together this week and note how it went.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a coping activity that works better together"}, {"id": "f1", "type": "textarea", "label": "Partner B: a coping activity that works better together"}, {"id": "f2", "type": "textarea", "label": "How we will offer one to each other"}, {"id": "f3", "type": "textarea", "label": "What we tried this week"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['coping skills', 'couples', 'support']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('coping-skill-effectiveness-rating-card', 'Coping Skill Effectiveness Rating Card', 'dbt'::resource_kind, 'Rates how effective each coping skill actually was after using it, building a data-backed list over time.', 'Replace guessing which skill works with a client''s own effectiveness ratings.', array['Adults', 'Teens']::text[], 'Ongoing', 'After using a coping skill, have the client rate how much it actually helped, not how much it should have helped in theory. Some skills that sound good on paper turn out to do little for a particular client, and this log catches that quickly. Reorder the client''s go-to list based on the ratings rather than a general recommendation.', '[{"id": "f0", "type": "textarea", "label": "The skill I used"}, {"id": "f1", "type": "textarea", "label": "The situation"}, {"id": "f2", "type": "textarea", "label": "How much it actually helped, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Whether I would use it again for this kind of moment"}]'::jsonb, array['coping skills', 'core DBT', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('coping-skill-willingness-to-use-check', 'Coping Skill Willingness to Use Check', 'act'::resource_kind, 'Checks whether a client is actually willing to use a coping skill they already know, and what gets in the way.', 'Address the gap between knowing a skill and being willing to reach for it in the moment.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to name a coping skill they already know works, then explore what gets in the way of actually using it: it feels silly, it takes too long, it means admitting they are struggling. Knowing a skill and being willing to use it are different things, and this names the gap directly. Practice one small willingness step toward using the skill despite the discomfort.', '[{"id": "f0", "type": "textarea", "label": "A skill I already know works"}, {"id": "f1", "type": "textarea", "label": "What gets in the way of using it"}, {"id": "f2", "type": "textarea", "label": "What using it would mean I am admitting"}, {"id": "f3", "type": "textarea", "label": "A small willingness step I could take"}, {"id": "f4", "type": "textarea", "label": "When I want to try it this week"}]'::jsonb, array['coping skills', 'willingness', 'core ACT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('coping-skill-belief-audit', 'Coping Skill Belief Audit', 'cbt'::resource_kind, 'Checks the client''s beliefs about a coping skill against how it has actually performed when tried.', 'Correct an outdated belief about a skill that is quietly stopping the client from using it.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client what they believe about a coping skill they rarely use, such as it won''t work for me or it''s a waste of time, then compare that belief against what actually happened the times they tried it. Beliefs about a skill often outlast the evidence, especially after one bad early attempt. Decide together whether the belief still holds up.', '[{"id": "f0", "type": "textarea", "label": "A coping skill I rarely use"}, {"id": "f1", "type": "textarea", "label": "What I believe about it"}, {"id": "f2", "type": "textarea", "label": "What actually happened the times I tried it"}, {"id": "f3", "type": "textarea", "label": "Whether the belief still holds up"}, {"id": "f4", "type": "textarea", "label": "What I want to try differently"}]'::jsonb, array['coping skills', 'core CBT', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('coping-skill-access-points-map', 'Coping Skill Access Points Map', 'worksheet'::resource_kind, 'Maps where a client''s coping skills actually live, so a skill is reachable in the moment it is needed.', 'Close the gap between knowing a skill and having it within reach when it counts.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client list their go-to coping skills, then note where each one is actually accessible: a phone note, a card in a bag, something that needs no object at all. A great skill that lives only in a notebook at home is not useful during a hard moment away from it. Fix any skill that has no real access point before moving on.', '[{"id": "f0", "type": "textarea", "label": "A coping skill I rely on"}, {"id": "f1", "type": "textarea", "label": "Where it is actually accessible right now"}, {"id": "f2", "type": "textarea", "label": "A skill with no clear access point"}, {"id": "f3", "type": "textarea", "label": "How I will fix that"}]'::jsonb, array['coping skills', 'self-monitoring', 'planning']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('willingness-to-approach-the-feared-thing-practice', 'Willingness to Approach the Feared Thing Practice', 'act'::resource_kind, 'Rates a client''s willingness to approach the feared object or situation, separate from expecting fear to be gone.', 'Decouple approaching a feared thing from needing to feel calm about it first.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to rate their willingness to approach the feared thing today, regardless of how much fear shows up, since waiting to feel ready often means waiting indefinitely. Distinguish willingness from courage or confidence; willingness only requires being willing to feel afraid while still moving toward the thing. Practice one small approach step at the current willingness level.', '[{"id": "f0", "type": "textarea", "label": "The feared thing"}, {"id": "f1", "type": "textarea", "label": "My willingness to approach it today, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I am afraid feeling will do if I approach anyway"}, {"id": "f3", "type": "textarea", "label": "A small approach step that fits my current willingness"}, {"id": "f4", "type": "textarea", "label": "What happened when I tried it"}]'::jsonb, array['phobias', 'willingness', 'core ACT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('phobia-safety-behavior-checklist', 'Phobia Safety Behavior Checklist', 'cbt'::resource_kind, 'Lists the small safety behaviors a client uses around a feared thing and what each one may be maintaining.', 'Spot the safety behaviors that quietly keep a phobia intact even during approach attempts.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client list small things they do to feel safer around the feared object, such as always having an exit route or a person nearby, and ask what belief each behavior might be protecting. Safety behaviors can undercut exposure by never letting the client fully test the fear. Choose one safety behavior to drop during the next planned approach.', '[{"id": "f0", "type": "textarea", "label": "A safety behavior I use"}, {"id": "f1", "type": "textarea", "label": "What belief it might be protecting"}, {"id": "f2", "type": "textarea", "label": "Another safety behavior"}, {"id": "f3", "type": "textarea", "label": "What it might be protecting"}, {"id": "f4", "type": "textarea", "label": "One I want to drop during my next approach"}]'::jsonb, array['phobias', 'safety behaviors', 'core CBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('feared-thing-storybook-craft', 'Feared Thing Storybook Craft', 'kids'::resource_kind, 'A child draws a short comic-style story about being brave near their feared thing, one panel at a time.', 'Let a child rehearse bravery in imagination before practicing it for real.', array['Children']::text[], '25 minutes', 'The parent helps the child draw a short comic of themselves being brave near the feared thing, one panel at a time, narrating what helps them feel steady in the story. Rehearsing bravery in a drawn story first makes the real practice feel more familiar when it comes. Read the finished comic together before any real-life approach step and let the child add to it as practice continues.', '[{"id": "f0", "type": "textarea", "label": "My feared thing"}, {"id": "f1", "type": "textarea", "label": "What my brave character does in the story"}, {"id": "f2", "type": "textarea", "label": "What helps my character feel steady"}, {"id": "f3", "type": "textarea", "label": "How I felt making the comic"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('feared-situation-companion-plan', 'Feared Situation Companion Plan', 'couples'::resource_kind, 'Scripts exactly what a supporting partner will say and do during each step of a feared-situation approach.', 'Remove guesswork for the supporting partner during a moment that is already stressful for both.', array['Couples']::text[], '20 minutes', 'Walk through the planned approach step by step and decide in advance what the supporting partner will say at each stage: before, during, and if the anxious partner wants to stop. Improvising support in the moment often backfires, either by pushing too hard or by rescuing too soon. Debrief afterward on what to adjust for the next approach.', '[{"id": "f0", "type": "textarea", "label": "The approach step we are planning for"}, {"id": "f1", "type": "textarea", "label": "What Partner B will say before"}, {"id": "f2", "type": "textarea", "label": "What Partner B will say during"}, {"id": "f3", "type": "textarea", "label": "What happens if Partner A wants to stop"}, {"id": "f4", "type": "textarea", "label": "What we want to adjust next time"}]'::jsonb, array['phobias', 'couples', 'exposure']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('phobia-approach-distress-log', 'Phobia Approach Distress Log', 'dbt'::resource_kind, 'Logs distress ratings before, during and after each approach attempt to show the trend across attempts.', 'Give the client their own evidence that distress during approach attempts tends to drop over time.', array['Adults', 'Teens']::text[], 'A few minutes per attempt', 'After each approach attempt, have the client log distress before, at the peak, and after, without needing to make the approach perfect. Comparing several logged attempts usually shows a downward trend even when any single attempt still felt hard. Use the trend, not any one entry, as the evidence worth pointing to.', '[{"id": "f0", "type": "textarea", "label": "The approach attempt"}, {"id": "f1", "type": "textarea", "label": "Distress before, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Distress at the peak"}, {"id": "f3", "type": "textarea", "label": "Distress after"}, {"id": "f4", "type": "textarea", "label": "How this compares to earlier attempts"}]'::jsonb, array['phobias', 'self-monitoring', 'core DBT']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('body-neutral-compliment-swap', 'Body Neutral Compliment Swap', 'game'::resource_kind, 'Group members trade compliments about what a body does rather than how it looks.', 'Practice a function-focused way of complimenting that steers clear of appearance entirely.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Have members take turns naming something another member''s body has let them do, such as run after a bus, hug someone, or dance badly and happily at a wedding, keeping every compliment about function and never about appearance. Redirect gently if an appearance comment slips in. Debrief on how this kind of compliment felt to give and to receive compared to the usual kind.', '[{"id": "f0", "type": "textarea", "label": "The function-focused compliment I gave"}, {"id": "f1", "type": "textarea", "label": "The one I received"}, {"id": "f2", "type": "textarea", "label": "How receiving it felt compared to an appearance compliment"}, {"id": "f3", "type": "textarea", "label": "A function-focused compliment I could give myself"}]'::jsonb, array['body image', 'group', 'play']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('body-talk-audit-at-home', 'Body Talk Audit at Home', 'worksheet'::resource_kind, 'Maps the appearance-focused comments a client hears regularly and where they tend to come from.', 'Make an environment''s steady stream of appearance talk visible enough to start setting limits around it.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client list where appearance-focused comments come up most, whether that is family gatherings, certain friends, or particular apps, and rate how much each source affects their day. Some sources can be limited or muted; others need a different kind of boundary, like changing the subject on purpose. Choose one source to address this week.', '[{"id": "f0", "type": "textarea", "label": "A source of appearance talk"}, {"id": "f1", "type": "textarea", "label": "How much it affects my day, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Another source"}, {"id": "f3", "type": "textarea", "label": "How much that one affects my day"}, {"id": "f4", "type": "textarea", "label": "One source I want to address this week"}]'::jsonb, array['body image', 'boundaries', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('bodies-are-for-doing-poster-craft', 'Bodies Are for Doing Poster Craft', 'kids'::resource_kind, 'A child builds a growing poster of things their body let them do this week, added to daily.', 'Build a child''s habit of noticing what their body does rather than how it looks.', array['Children']::text[], '15 minutes to start, then daily', 'Each day, the child adds a small drawing or sticker to a poster showing something their body let them do, like climbing, laughing hard, or riding a bike, with the parent asking about it rather than commenting on appearance at any point. Keep the poster entirely about doing and feeling. Look at the growing poster together at the end of the week.', '[{"id": "f0", "type": "textarea", "label": "What my body let me do today"}, {"id": "f1", "type": "textarea", "label": "How it felt to do it"}, {"id": "f2", "type": "textarea", "label": "My favorite thing on the poster so far"}, {"id": "f3", "type": "textarea", "label": "What I want to try doing next"}]'::jsonb, array['body image', 'children', 'play']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('appearance-comparison-interrupt-sheet', 'Appearance Comparison Interrupt Sheet', 'cbt'::resource_kind, 'Interrupts an in-the-moment appearance comparison with a short, practiced redirect.', 'Give the client a fast response to reach for the moment a comparison starts rather than after it spirals.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to notice the exact moment an appearance comparison starts, then practice a short redirect, such as naming one function-based thing about their own body or shifting attention to the present task. The goal is interrupting early, before the comparison has a chance to spiral into a longer, harsher thought chain. Rehearse the redirect a few times in session before expecting it to hold up in the moment.', '[{"id": "f0", "type": "textarea", "label": "A recent moment a comparison started"}, {"id": "f1", "type": "textarea", "label": "What triggered it"}, {"id": "f2", "type": "textarea", "label": "The redirect I want to practice"}, {"id": "f3", "type": "textarea", "label": "When I want to try it this week"}]'::jsonb, array['body image', 'core CBT', 'self-monitoring']::text[], '2026-09-27T15:00:00+00:00'::timestamptz),
  ('body-talk-boundaries-as-a-couple', 'Body Talk Boundaries as a Couple', 'couples'::resource_kind, 'Agrees together on how the couple wants to handle body talk, including comments about other people''s bodies.', 'Extend a couple''s body-talk agreement beyond comments about each other to a shared household norm.', array['Couples']::text[], '20 minutes', 'Ask both partners how body talk shows up at home, including offhand comments about other people''s appearance, and agree on what kind of talk the household wants to keep or drop. This widens an existing agreement about comments to each other into a broader shared norm. Revisit the agreement if it slips, without turning the check-in into blame.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how body talk shows up at home"}, {"id": "f1", "type": "textarea", "label": "Partner B: how body talk shows up at home"}, {"id": "f2", "type": "textarea", "label": "What we want to keep"}, {"id": "f3", "type": "textarea", "label": "What we want to drop"}, {"id": "f4", "type": "textarea", "label": "How we will check in if it slips"}]'::jsonb, array['body image', 'couples', 'communication']::text[], '2026-09-27T15:00:00+00:00'::timestamptz)
